/* 原创数据结构白话图解。数组下标从 0 开始，所有小输入用于手工追踪。 */
(() => {
  const target=window.PLAIN_BEGINNER=window.PLAIN_BEGINNER||{};
  function add(id,plainTitle,goal,story,terms,kind,nodes,steps,caption,boundary){target[id]={plainTitle,goal,story,terms:terms.map(([word,meaning,example])=>({word,meaning,example})),diagram:{kind,nodes:nodes.map(([name,detail])=>({name,detail})),caption},steps:steps.map(([title,text])=>({title,text})),boundary};}
  add('ds-sorting-foundations','分数相同，原先前面的同学还能在前吗？','在带身份的记录上判断稳定性，并区分比较、移动与额外空间。',
    '三张成绩卡按先后是 2分甲、1分丙、2分乙，排序后丙应在前，但甲乙都为二分。若甲仍在乙前，叫保持相等键的原先次序，也就是稳定。单看数字 1、2、2 看不出差别，所以理解排序不仅要盯是否递增，还要看记录身份、搬动次数与用了多少额外位置。',
    [['关键字／记录','关键字决定比较大小，记录还带其他数据或身份。','分数 2、姓名甲。'],['稳定排序','相等关键字的记录保留原先相对次序。','二分甲仍先于二分乙。'],['比较与移动','比较判断顺序，移动改变记录存放位置，二者成本可不同。','长记录搬运可能更贵。']],
    'compare',[['原先记录','2甲、1丙、2乙'],['稳定结果','1丙、2甲、2乙'],['仅数字不够','1、2、2 无法判断稳定']],
    [['先给同值记录加上身份','只写两个 2 无法区分先后，于是标为 2甲与 2乙。排序依据只看分数，不拿名字再比大小；否则任务变成按两种关键字排序，讨论的稳定性前提也变了。'],['稳定是算法规则的保证','结果甲在乙前符合本次稳定要求，但一次例子未打乱不能证明整个算法稳定。应检查比较相等时的移动、合并或跨越是否总能保留原有相对顺序。'],['再按使用约束选算法','数据量、取值范围、是否近乎有序、内存是否够，都影响选择。渐近比较次数、记录移动与额外空间是不同指标，不能把“原地”直接等同“最快”，也不能只凭名字决定。']],
    '记录按分数升序，甲丙乙只作身份标签，不参与比较。','稳定性对完整记录有意义；若只输出各值出现次数，已丢失身份信息，就不能据此声称实现了稳定记录排序。');
  add('ds-insertion-sort','新来一张卡，怎样插进已经排好的一段？','保持左边有序，把较大项右移后放入新值。',
    '手里已有从小到大的 2、5，新摸到 3。先把 3 暂存，5 太大向右挪一格，2 不大于 3，就把 3 放在它后面，成为 2、3、5。插入排序每轮只接纳一个新元素，左边的有序段逐渐长大。折半查插入位置能减少比较，却不会让需要搬的卡片自动消失。',
    [['有序前缀','当前已经排好顺序的数组开头一段。','先是 2、5。'],['插入位置','新值放入后仍保持有序的位置。','3 应放在 2 与 5 之间。'],['折半插入','在有序前段用二分寻找位置，再搬移插入。','定位快不等于移动少。']],
    'timeline',[['原有序段','2、5；新值 3 暂存'],['给 3 腾位','5 右移，2 留下'],['放回新值','2、3、5']],
    [['先把新值保护在外面','取出新值 3 暂存，左段 2、5 已有序。若边搬移边直接覆盖尚未保存的新值，可能把原输入弄丢；这一轮的目标是把有序前缀从两项增加到三项。'],['只移动严格更大的项','从右往左比较，5 大于 3，向右移；2 不大于 3，就停止并把 3 放后面。若相等时不让新记录跨过旧记录，可维持稳定次序。'],['区分找位置与腾位置','普通插入逐个比较，折半插入可用二分少做比较，但中间插入仍可能搬很多项。近乎有序时简单插入常很合适；一般逆序输入仍会产生平方级移动。']],
    '一轮插入：有序前缀 2,5 接纳新值 3；不是一次排完整个任意长数组。','折半定位相等元素时选左界还是右界影响稳定性；只背“二分查找”并不能自动保证相等记录次序。');
  add('ds-shell-sort','先隔几格整理，再把步子缩小','用间隔为三的分组理解希尔排序，不把组内有序当成全局有序。',
    '数组 9、1、8、2、7、3 中，大数九与小数二隔得远，普通插入要挪很多位置。希尔先隔三格看一组：9和2、1和7、8和3，各组先做插入整理，得到 2、1、3、9、7、8，再用步长一整理全体。大步先处理远处错位，小步补齐最后秩序。',
    [['增量／步长','同一轮比较的同组相邻位置相差多少。','步长三时下标 0、3 同组。'],['分组插入','分别对同余位置组成的子序列做插入排序。','9、2 排成 2、9。'],['增量序列','若干轮使用的步长安排，通常最后为一。','本例依次 3、1。']],
    'timeline',[['步长 3 分组','(9,2)、(1,7)、(8,3)'],['各组有序后','2、1、3、9、7、8'],['步长缩到 1','1、2、3、7、8、9']],
    [['同组不是一块连续片段','步长三把下标 0、3 分在一起，1、4 一组，2、5 一组。别把数组直接切成前后三项两块，那是另一种分组，不是这轮的等间隔子序列。'],['只承诺每个等间隔组有序','交换后数组为 2、1、3、9、7、8，仍然有 2 大于后面的 1，所以不能把某轮完成当作全部排序完成。组内插入使一些远距离错位提前缩短。'],['最后一步长一确保整体有序','步长一时全数组成为一个组，再按插入规则完成。效率与步长序列密切相关，不能不写增量条件就笼统声称所有希尔排序都是固定一种增长阶。']],
    '输入 9,1,8,2,7,3；先用步长三，再用步长一，各组仍位于原下标上。','希尔排序一般不稳定；跨组移动可能让相等记录互相越过。具体复杂度必须结合增量序列讨论。');
  add('ds-bubble-selection','都把小数放前面，交换方式为什么不同？','区分相邻交换推动极值与扫描整段后一次选择。',
    '数组 3、1、2，冒泡从左比相邻两项：3 大于 1 就换，再把 3 与 2 换，最大数被推到右边。选择排序则先扫描整段，找到最小值 1，再与第一项交换。两者都在扩大已确定区，但比较的是哪些对象、每轮确定哪一端、移动多少记录，都不一样。',
    [['冒泡排序','用相邻比较交换把某个极值逐步推向边界。','一轮把最大 3 推到末尾。'],['选择排序','从未排序段选最小或最大，再与边界项交换。','先选出最小 1。'],['已确定区','后续轮次不再改变的正确位置区域。','冒泡升序右端逐渐固定。']],
    'compare',[['冒泡一轮','3,1,2 → 1,2,3'],['选择第一轮','3,1,2 → 1,3,2'],['后续处理','缩小各自未排序区']],
    [['冒泡让元素一步一步走','先比较 3 与 1，换成 1、3、2；再比较 3 与 2，换成 1、2、3。只用相邻交换，且相等不换时，可保留同键记录的相对顺序。'],['选择先记住最好候选的位置','扫描 3、1、2 后，知道最小值在下标一，再与下标零交换，变成 1、3、2。这里不是看见更小就马上交换，而是整轮确定最小位置再统一移动。'],['不要把同级复杂度当成同算法','一般两者都可有平方级比较，但移动模式不同。选择的一次远距离交换可能让相等记录越位，普通实现不稳定；冒泡的提前无交换退出优化，也需看具体输入。']],
    '输入同为 3,1,2；两行给出各自第一轮结果，用于比较行为，不要求中间状态相同。','稳定性依具体比较交换规则。改成特殊稳定选择版本会增加移动成本，不能把改造版结论当成普通版本事实。');
  add('ds-quicksort','先把比基准小的分一边，两边就排好了吗？','区分分区与排序完成，再递归处理左右区域。',
    '桌上 4、2、5、1、3，先选 3 当分界，把更小的 2、1 放左边、更大的 4、5 放右边。此时 3 的相对位置确定，但左边 2、1 还没排好。快速排序不断对两边做同样的分区；“分完一轮”不是“所有元素已排序”，这点比背指针移动顺序更先要理解。',
    [['基准／pivot','本轮拿来划分较小与较大区域的参考值。','选择 3。'],['分区','按与基准关系把元素重新安排成几个区域。','小于 3 的到左边。'],['递归区间','分区后仍需独立处理的剩余部分。','继续排 2、1。']],
    'branches',[['一轮分区','2、1｜3｜4、5'],['左边仍未排好','2、1 继续处理'],['合成结果','1、2、3、4、5']],
    [['先说明本轮想保证什么','本图使用“基准单独就位”的分区语义：左边都较小，右边都较大。具体搬移过程有多种写法，不能把这里的示意中间排列当作所有分区程序唯一的执行结果。'],['基准就位不等于区域内部有序','得到 2、1｜3｜4、5 时，所有左项小于 3，却仍然 2 在 1 前。还要对左区、右区分别递归；空区或单元素区直接完成，边界必须真的缩小。'],['数据重复和选基准影响工作','如果每轮只分出一个很小区，递归可能接近线性深度，总比较退到平方级；划分较均衡时通常较好。大量同值输入可考虑三路分区，不能随意省略相等条件。']],
    '互异输入 4,2,5,1,3 选基准 3；图只规定区域关系，不指定 Lomuto 或 Hoare 搬移细节。','不同分区方法返回点的含义不同，递归边界必须配套；不能把某方法的返回值当成另一方法的最终基准位置。');
  add('ds-merge-sort','两个队伍都排好了，合在一起怎样不乱？','每次只比较两边头部，理解归并排序的拆分与合并。',
    '两列卡片分别已经排成 1、4 和 2、3。每次比较两列最前面，先拿较小的 1，再拿 2、3，剩下 4 接尾，就成整体顺序。归并排序先把大段分成更小段，让各段排好，再用这个可靠合并动作逐层拼回；不是把两段简单贴起来。',
    [['归并','把几个有序序列合成为一个有序序列。','1,4 与 2,3 变 1,2,3,4。'],['分治','把问题分成较小子问题，再组合其结果。','先分别排左右半段。'],['稳定合并','相等时优先取原先更靠前那段的记录。','左边同键先输出。']],
    'flow',[['原数组拆开','4,1｜3,2'],['各段先有序','1,4｜2,3'],['头部逐次归并','1、2、3、4']],
    [['小段先解决再要求有序','4、1 和 3、2 还不能直接按“两边头部最小”的规则全程保证正确，要先分别排为 1、4 和 2、3。递归到单元素时天然有序，再向上合并。'],['只需比较当前两边的头部','因为每段已递增，头部就是该段余下最小。比较一和二先取一，再比四和二取二，再比四和三取三，最后把剩余四接上，不必每轮重新扫描全段。'],['记录额外空间与相等选择','常见数组归并用临时区域保存输出，所以除递归状态还需额外数组。相等时优先取左边可保持稳定，若随意先取右边，同值身份顺序就可能改变。']],
    '输入 4,1,3,2；中间两段已经各自排好，合并保持递增。','链表归并可通过接线而非同样大的临时数组完成；空间结论应与具体表示和实现配套说明。');
  add('ds-heapsort','每次把最大值放到末尾，剩下继续比','在有效堆和已排序后缀之间维持清楚边界。',
    '最大堆让最值位于根，正好可以反复拿来确定末尾：把根与最后一个有效元素交换，最大值就归位；剩下的根可能太小，需要下沉恢复堆，再取新的最大。数组于是分成左边“还在竞争”的堆和右边“已经排好不再动”的后缀，边界每轮缩一格。',
    [['最大堆','父值不小于孩子、根为当前最大值的完全二叉结构。','4、2、3、1 是一个堆。'],['有效堆长度','当前仍参与堆操作的前段元素数量。','归位 4 后从四缩到三。'],['下沉修复','把过小的根与较大孩子交换，继续检查。','根 1 下沉后最大 3 到根。']],
    'timeline',[['4 归位','先换到数组末尾'],['剩三项修复','前段变 3、2、1'],['3 再归位','最终得到 1、2、3、4']],
    [['先确保前段本来就是堆','本例初始堆为 4、2、3、1。若输入任意排列，先建堆。把根四与末项一交换后为 1、2、3、4，只能确定四已正确，不能直接说整个数组排完。'],['收缩后再修，不碰归位元素','有效长度缩为三，四位于排序后缀不再参加比较。前段根一比较大孩子三小，下沉后前段为 3、2、1；如果把末尾四仍算进堆，刚归位的最大值会被拉回来。'],['重复得到递增的排序后缀','再把根三放到有效堆末端，长度缩二并修复，继续直到剩一项。每轮确定当前最大值放右边，所以最终数组递增；交换跨越距离，普通堆排序不稳定。']],
    '初始层序数组 4,2,3,1；每轮分开标记有效堆前缀与已归位后缀。','堆数组本身并非整体有序，只有完整执行取根、缩堆、修复过程才形成排序；稳定性也不是堆属性。');
  add('ds-counting-sort','值只在几个数字里，能直接数每种有几张吗？','用计数表替代比较，理解成本与取值范围有关。',
    '卡片只可能写 0、1、2，拿到的是 2、0、2、1。先分别数出零一张、一一张、二两张，再按数值顺序输出，就得到 0、1、2、2，不必让卡片两两比较。这种办法利用了取值范围小的条件；如果值可能从零到十亿，为每个值准备一格就不再划算。',
    [['计数表','每个合法值对应一个记录出现次数的位置。','count[2]＝2。'],['取值范围 k','需要为多少种可能值提供计数位置。','0、1、2 共三种。'],['累积计数','把到某值为止的个数加起来，用来推导输出位置。','小于等于 1 的有两项。']],
    'flow',[['扫描输入','2、0、2、1'],['统计次数','0:1，1:1，2:2'],['按值还原','0、1、2、2']],
    [['先建立值到计数位置的映射','本例值为零到二，直接用值作下标，初始三个计数都是零。每读一项给对应格加一。若最小值不是零，可减去最小值偏移，但还须确保范围和内存可承受。'],['计数阶段不需要两两比大小','输入依次让二、零、二、一的计数增加，得到 1、1、2。总成本包含扫描 n 项与处理 k 个计数格，所以写成 n＋k 相关，而不是无条件只有 n。'],['完整记录的稳定输出另有步骤','只输出数字时按次数写回即可。若记录还带姓名等内容，单有次数不保留身份；稳定版本要用累积位置并按匹配的方向放记录，不能说统计次数后自然就稳定。']],
    '输入 2,0,2,1，允许值恰为 0 到 2；图仅演示纯整数输出。','计数排序适用于可合理映射的离散小范围键。它突破比较排序下界依赖额外条件，并非推翻该下界的前提。');
  add('ds-radix-sort','个位排完，再排十位时为什么不能乱插？','用稳定的逐位排序把已处理低位信息保留下来。',
    '三张两位卡是 21、13、12。先按个位稳定排，得到 21、12、13；再按十位稳定排，十位同为一的 12、13 保持之前先后，得到 12、13、21。如果第二轮把十位相同的卡随意打乱，第一轮辛苦排好的个位关系就可能失效。基数排序靠每一轮稳定地继承旧顺序。',
    [['位／数位','按固定进制表示时的一处数字位置。','十位与个位。'],['LSD 基数排序','从最低位向高位逐轮进行稳定排序的方法。','先个位，再十位。'],['稳定分配收集','同一数位值的记录保持原先相对次序。','十位相同的 12 仍先于 13。']],
    'timeline',[['原记录','21、13、12'],['按个位稳定排','21、12、13'],['按十位稳定排','12、13、21']],
    [['每轮只按当前数位分组','个位分别为一、三、二，因此第一轮是 21、12、13。不要拿整值把它提前排序；本轮只建立已处理最低一位的顺序，整体尚未保证递增。'],['高一位相同则继承旧顺序','第二轮十位一的 12、13 应按上一轮次序进入同一桶并保持，所以 12 在 13 前，十位二的 21 随后。若同桶用后进先出反转，低位次序会被破坏。'],['处理完足够位数才结束','所有参与比较的位完成后得到整体顺序。位数 d、每轮输入规模 n、桶数 r 都影响成本；不同长度或负数需要先有一致表示与处理规则，不能直接套正两位数例子。']],
    '十进制、两位非负整数的 LSD 示例；每轮按数位升序且稳定。','MSD 从高位开始的分治规则不同；稳定性要求和递归方式要按具体版本讨论，不把两个名字混成同一流程。');
  add('ds-external-sort','数据装不进内存，怎么在磁盘上慢慢排？','先生成有序段，再多路归并，关注读写趟数而非只数比较。',
    '有十二箱资料，工作台一次只能放三箱，不可能把全体同时摊开排。先每三箱整理成一段有序资料放回磁盘，再从各段前端分批读入，挑最小项写到输出，合成更长有序段。外部排序最花钱的常是来回读写大文件，怎样减少归并轮数比只少几次比较更重要。',
    [['外部排序','数据不能全部留在主存中，需要配合外部存储的排序。','大文件分批处理。'],['有序段／run','已经按规则排好的一段连续记录序列。','每批三箱先排成一段。'],['多路归并','同时从多条有序输入取最小头部，合成一条有序输出。','四段一起归并。'],['缓冲区','在内存里批量暂存待读或待写数据的区域。','每段各留输入缓冲。']],
    'flow',[['分批内排','十二箱分成四批，每批三箱'],['生成四段','各段内部已经有序'],['批量多路归并','读各段头部，输出全序']],
    [['先产生能实际放下的有序段','每次读入不超过工作内存的一批，内部排序后写成初始有序段。不是把一小段排好就原地覆盖所有未读数据，必须保护文件输入与输出区域的契约。'],['归并要给每路与输出留缓冲','同时比较各段当前头部，选择最小并从对应路继续读取。内存不能全给输入，还要留输出缓冲和管理结构，因此可用归并路数由实际内存预算决定。'],['增加路数是为了减少大规模往返','更多路在一轮合并更多段，常能减少全文件读写趟数，但也增加缓冲管理与选最小的工作。磁盘访问、块大小和设备特性影响真实时间，不能只看 CPU 比较次数下结论。']],
    '“箱”是记录批量的类比，展示先生成有序段、再归并；不要求磁盘一次真的只读三条记录。','图忽略具体文件格式与块尺寸。归并路数、置换选择和败者树是进一步优化，须在缓冲预算明确后分析。');
})();
(() => {
  const target=window.PLAIN_BEGINNER=window.PLAIN_BEGINNER||{};
  function add(id,plainTitle,goal,story,terms,kind,nodes,steps,caption,boundary){target[id]={plainTitle,goal,story,terms:terms.map(([word,meaning,example])=>({word,meaning,example})),diagram:{kind,nodes:nodes.map(([name,detail])=>({name,detail})),caption},steps:steps.map(([title,text])=>({title,text})),boundary};}
  add('ds-binary-boundaries','找到了一个 2，怎么知道它是不是最左边？','用半开区间保持候选范围，找第一个不小于目标的位置。',
    '有序号码 1、2、2、4，随便找到一个 2 不等于知道重复段从哪里开始。想找最左边界，就不断问中间那项是否已经达到 2：达到就保留它和左边，没达到才丢掉它及更左边。二分不仅是“折半”，更要说明被留下的范围始终包含什么答案。',
    [['有序','按给定比较规则排好先后。','1≤2≤2≤4。'],['半开区间 [l,r)','包括下标 l，不包括下标 r 的候选范围。','[0,4) 含 0、1、2、3。'],['lower_bound','第一个不小于目标的位置，也可能在末尾。','本例目标 2 的边界为 1。']],
    'timeline',[['范围 [0,4)','中间 2，值为 2'],['收右端到 2','范围 [0,2)，再查 1'],['收右端到 1','再排除 0，答案为 1']],
    [['先把要找的答案说完整','目标不是随便一个 2，而是第一个值至少为 2 的位置。候选范围从 [0,4) 开始；右端四表示可用的末尾边界，不代表数组真的有下标四的元素。'],['根据条件保留正确的一侧','中间下标二的值达到目标，答案可能是它，也可能在左边，所以 r 变二；再查下标一同样达到，r 变一。若值小于目标，应令 l 为中点加一，确保本轮前进。'],['区间合拢后核对实际命中','最后检查下标零的 1，小于目标，l 变一，与 r 相等，答案边界为一。若题目要求“确实存在目标”，还须检查该位置未越末尾且值等于目标。']],
    '数组 1,2,2,4 查目标 2 的左边界；中间位置按向下取整计算。','右边界通常找第一个大于目标的位置，比较符号不同。不能混用闭区间更新式与半开区间终止条件。');
  add('ds-indexed-block-search','先找哪一盒，再翻盒里的卡','利用块间范围有序，把查找限制到一个块内。',
    '九张卡分成三盒：第一盒 2、1、3，第二盒 6、4、5，第三盒 9、7、8。盒里不必排好，但前一盒的所有数都小于后一盒。找 5 时先看各盒的最大值 3、6、9，锁定第二盒，再只翻这一盒。分块查找把全体规则与局部查找拆开。',
    [['块','把数据划成若干份的一份。','第二盒为 6、4、5。'],['索引','记录各块位置与范围边界的辅助信息。','最大值 3、6、9。'],['块间有序','前面块与后面块满足规定的整体大小关系。','第一块的数全小于第二块。']],
    'flow',[['索引 3、6、9','首个达到 5 的边界是 6'],['锁定第二块','只检查 6、4、5'],['块内逐项找','第三项找到 5']],
    [['先确认索引真的能划范围','每块最大值为 3、6、9，而且前块所有元素小于后块。只知道三个最大值有序，却没有块间分界保证，不一定能据此排除其他块，必须检查题目给的条件。'],['用索引找到可能的块','找 5，最大值三不足以容纳目标，最大值六是第一个达到五的边界，因此进入第二块。索引有序时可顺序或二分查索引，这一成本也算在总查找里。'],['块里仍要按实际布局检查','第二块内部是 6、4、5，并非有序，不能未经条件直接二分。逐项比较后找到五；若没有找到就报告不存在，并非索引范围包住它就保证存在。']],
    '三个块各三项，块内无序但块间整体有序；本图查值 5。','索引维护有成本，插删后也须更新边界和块内容。分块大小选择影响索引工作与块内扫描的权衡。');
  add('ds-hash-chaining','算出同一个抽屉，为什么还要比较钥匙？','用余数分桶理解冲突与拉链法，不把散列当作唯一编码。',
    '给钥匙号 7、12、17 各找一个抽屉，规则是除以五取余数，结果都为二。这不表示它们是同一把钥匙，而是规则把它们放进同一桶。拉链法在这个桶里继续保存几条记录，找 12 时先算桶号，再逐项核对完整钥匙，冲突解决了但比较没有凭空消失。',
    [['关键字','用于识别或查找记录的值。','钥匙号 12。'],['散列函数','把关键字映到有限桶编号的规则。','h(k)=k%5。'],['冲突','不同关键字得到同一个桶编号。','7、12 都映到二。'],['拉链法','每桶再用一串记录等结构保存碰撞项。','桶二保存 7、12、17。']],
    'flow',[['计算桶号','7、12、17 除 5 都余 2'],['桶 2 保存多项','记录链 7→12→17'],['查 12 仍比较','先比 7，再比 12']],
    [['先把函数当成分组规则','h(k)=k%5 里 k 是关键字，% 表示取余数，桶编号为零到四。编号少于可能关键字时，不同键落同桶很正常，不能因为冲突就判函数失效。'],['桶内仍保留完整关键字','把 7、12、17 作为三个不同记录存在桶二的链中。只存余数会无法区别它们，散列值相同不是数据相等；判断相等仍需要完整关键字和约定的比较规则。'],['比较成本取决于分布与装填','查 12，先算出桶二，再沿链比较到 12。分布合适时链短，查找平均较快；若所有键挤同一桶，可能仍需线性扫描，不能宣称任何输入都一次完成。']],
    '表容量五，桶二采用记录链 7→12→17；箭头表示桶内连接，不是数值大小排序。','通常的平均常数查找有分布和装填假设。链也可由其他桶内结构替代，不能把抽象桶误等同于唯一实现。');
  add('ds-open-addressing','原位被占，顺着找；删掉后为何要留记号？','沿同一探测序列查找，区分从未使用与删除墓碑。',
    '五格表用“除五取余”定位，7 先放格二，12 也想去格二，只好依次探到格三。后来删掉 7，若把格二当成从未放过，查 12 到这里就可能误判不存在。墓碑标记告诉查找者：这里曾有记录，后面还可能有同一条探测路上的数据。',
    [['开放寻址','所有记录仍放表内，冲突后按规则寻找其他槽。','线性向后逐格试。'],['探测序列','为一个键按固定规则依次检查的位置。','2、3、4、0、1。'],['墓碑','表示此槽曾使用但已删除，查找不能据此立刻停止。','删掉格二的 7 后留标记。'],['装填率','表中有效记录数占槽数的比例。','五格有四项，比例 4/5。']],
    'timeline',[['插入 7、12','槽 2:7，槽 3:12'],['删除 7','槽 2 留墓碑，不当从未用'],['再找 12','经过墓碑，在槽 3 命中']],
    [['冲突后按可重复的路线走','7、12 的初始位置均为二，线性探测让 12 试三并放入。以后找 12 必须走同样路线，不能每次冲突随机换一条没有记录的路，否则可能跳过已有位置。'],['删除不能割断查找证据','删除格二的 7 后留墓碑。查询 12 到墓碑应继续，而见到从未使用的槽才可按该策略判断这条路上不存在；把两种空状态混在一起会漏查。'],['还要处理探测循环与压力','找到格三后核对完整键为 12。表接近满时探测可能变长，插入须防止绕一整圈无终止；墓碑也会影响成本，常需重新整理或扩容。']],
    '容量五、线性探测、初址 k%5；图展示删除后查询，未规定墓碑再插入的全部策略。','不同开放寻址策略有不同探测覆盖条件。墓碑复用时仍需检查后方是否已有同键，避免重复插入。');
  add('ds-bst','每比一次，就知道该往左还是右','在具体搜索树上按大小排除整棵子树。',
    '根写 5，左边整棵放比 5 小的数，右边整棵放比 5 大的数。左孩子 3 的右孩子再放 4，右孩子放 8。找 4 时先与 5 比，去左；与 3 比，去右；再命中 4。每次不是只排除一个数，而是按整片子树的范围规则选择方向。',
    [['二叉搜索树／BST','每个节点左子树键较小、右子树键较大的二叉树，重复键需另定规则。','根 5 左 3 右 8。'],['关键字比较','按目标与当前键的大小关系选择去向。','4＜5 去左。'],['退化','树形变成长链，查找不再有折半保证。','顺序插 1、2、3、4。']],
    'flow',[['当前 5','4＜5，去左子树'],['当前 3','4＞3，去右子树'],['当前 4','相等，找到']],
    [['规则约束整片而非只看孩子','5 的左子树所有键都小于 5，右边都大于 5；不是左孩子小就够了。因此目标 4 可以排除右边整片，沿左边继续，而不用逐个访问 8 等节点。'],['到新节点继续同一规则','来到 3 后，4 大于 3，所以走右孩子 4。每一层先做比较再前进，空连接表示这条合法候选路径结束；不能遇到叶子就不比较其值而直接判失败。'],['树的高度决定查找代价','此例三次比较找到 4。一般查找与路径高度相关，树若接近平衡可较短，若退成链就可能看很多点。BST 的有序性质不自动保证 O(log n)。']],
    '具体结构：5 左 3 右 8，3 右 4；其他孩子为空，关键字互异。','重复值可采用计数或固定侧等策略，但插入、查找、删除必须遵守同一约定；本例只讨论互异键。');
  add('ds-avl','树长歪以后，转一下为什么仍然有序？','用 3、2、1 插入例看右旋保持中序，并恢复高度差。',
    '依次插入 3、2、1，普通搜索树会形成向左的一条长链。AVL 在每个节点检查左右高度差，太偏就旋转。把中间的 2 提上来，3 成它的右孩子、1 留左边，查找先后关系还是 1、2、3，形状却更矮。旋转不是随意换数，而是同时保住范围关系。',
    [['AVL 树','每个节点左右子树高度差不超过一的平衡搜索树。','避免持续偏向一边。'],['平衡因子','按本课取左子树高度减右子树高度。','值超出 −1、0、1 要检查。'],['旋转','局部重新连接父子而保持搜索次序的变换。','左左失衡可作右旋。']],
    'timeline',[['插入 3、2、1','根 3，左 2，2 左 1'],['根部向右旋','2 上升，3 成右孩子'],['恢复平衡','根 2，左 1，右 3']],
    [['先识别失衡发生在哪里','原根 3 左边高度二，右边为空，差为二，违反 AVL 条件。本例插入路径连续向左，称左左情形；不是看到任意高度差二都无条件作同一种旋转。'],['旋转只改局部连接关系','把 2 提为这片子树根，原 3 接成 2 的右孩子，1 仍在 2 左侧。更一般的右旋还要把 2 原右子树转接给 3 的左侧，不能忽略这片中间范围。'],['同时核对次序与新高度','旋转前后中序均为 1、2、3，满足左小右大；新高度差也合格。实现时还须更新高度和上层入口，删除后可能要沿祖先继续检查，不能只修一次便默认全树结束。']],
    '本图是互异键 3、2、1 导致的左左失衡，采用一次右旋；不是所有 AVL 情况的通用图。','左右、右左等情况可能需要双旋。空子树高度定义可不同，但必须在整套高度与平衡计算中一致。');
  add('ds-red-black-intro','给节点涂颜色，怎么限制树别长得太歪？','把颜色当结构约束，认识禁止红连红与黑高一致的作用。',
    '红黑树不是把数字按颜色分类，也不是红色更大。它仍是左小右大的搜索树，颜色只是帮助维护形状的标签。一个简单合法例子是黑根 2、红左孩子 1、红右孩子 3，各个空孩子视作黑色。限制红色不能连续、各条向下路径黑节点数相同，就能约束最长路径不会过分失控。',
    [['红黑树','用颜色约束控制高度的一类平衡二叉搜索树。','颜色不改变键大小规则。'],['红连红','红节点又有红孩子的情况，违反对应规则。','新红节点接红父需要修复。'],['黑高','按统一约定统计向下到空叶路径上的黑节点数量。','同一起点各路径应一致。'],['NIL 空叶','用来表达空子树边界的黑色叶标记。','不是另一个业务键。']],
    'compare',[['仍须左小右大','1＜黑根 2＜3'],['红不能接红','红孩子的子位置为黑空叶'],['向下黑数一致','各分支按同一约定计数']],
    [['先保留原来的搜索树含义','例子里 1 在 2 左、3 在 2 右，这与红黑颜色无关。即使每个颜色都画对，若某个小键跑去不允许的右侧，仍不是正确搜索树，需分别检查两套要求。'],['颜色负责限制形状','红节点不能有红孩子，因此红色不会连续形成很长链。NIL 视为黑，根通常按约定保持黑色；红不是“新插入所以永远不变”的身份，修复中可能重新染色。'],['插删修复要维护全部约束','每条向下路径的黑节点数相同，配合不连续红色，限制最长与最短路径关系。插删后可能要旋转与换色；本课先认清约束，不凭“随便转平一点”代替具体修复规则。']],
    '合法小树为黑 2、红 1、红 3，其空孩子均按黑 NIL 处理；三块列出不同约束。','红黑树不要求每点左右高度差至多一，那是 AVL 的更严格条件。黑高计数是否含起点须看教材约定。');
  add('ds-btree-bplus','一次读一页，为什么页面里放很多路标？','用多关键字节点减少层数，分清 B+ 内部路标与叶子记录。',
    '磁盘上读一页常比在已读页面里多比较几个数更贵，于是一个节点里可以放多个分界值，让一次读取带来很多路标。B+ 树内部页像目录，真正记录放叶页；找 17 时读到分界 10、20，就沿中间范围去叶页。叶页再相连，还方便按范围连续读取。',
    [['多路搜索','一个节点用多个分界值选择多个子范围。','10、20 划出三段。'],['B 树／B+ 树','都是多路平衡搜索结构；常见 B+ 把记录集中在叶层，内部作索引。','B 树可在内部键处命中记录。'],['叶链／范围查询','把叶页顺序连接，便于从起点继续读后续记录。','查 12 到 25 的记录。']],
    'flow',[['内部路标 10、20','按分界选择范围'],['查值 17','走 10≤键＜20 的分支'],['到叶页核对','在 12、17 中找到记录']],
    [['先区分页内比较与跨页访问','内部节点一次包含多个键，分出多个孩子范围，使树高通常比二叉形式低。具体“阶数”指最大孩子数还是别的上限，教材可能不同，要先读定义再数节点容量。'],['内部关键字不必就是记录本身','本图用 B+ 分隔规则，小于十、十到二十之间、不小于二十分别去三条路。查十七先去中间，再到叶页比较完整键，不能在内部目录看见分界就当成全部数据。'],['插删还要维护页面与层高','页满可分裂、过少可借用或合并，保持叶子同层和容量约束。叶页相连支持范围顺序读，但不表示所有物理磁盘页地址连续，逻辑连接与物理布局仍应分开。']],
    '图是 B+ 树的一种分界约定：中段含 10、不含 20；叶页示例含 12、17。','B 与 B+ 的细节随实现而异，等于分隔值走哪边必须明确定义；不可把某一数据库页格式当成通用数学定义。');
})();
(() => {
  const target=window.PLAIN_BEGINNER=window.PLAIN_BEGINNER||{};
  function add(id,plainTitle,goal,story,terms,kind,nodes,steps,caption,boundary){target[id]={plainTitle,goal,story,terms:terms.map(([word,meaning,example])=>({word,meaning,example})),diagram:{kind,nodes:nodes.map(([name,detail])=>({name,detail})),caption},steps:steps.map(([title,text])=>({title,text})),boundary};}
  add('ds-graph-representation','一张路线图，怎样装进电脑？','把点与边分开，比较邻接矩阵和邻接表记录什么。',
    '三处站点 A、B、C，只有 A 与 B、A 与 C 有路。你可以画三乘三表，逐对记有没有连接；也可以给每个站列“直接能去哪些站”。前者像完整关系台账，后者像每站自己的路线清单。两种都表达同一张图，但占空间和查询方式不同，路线是否有方向也必须事先说清。',
    [['顶点／边','顶点代表对象，边代表对象间约定的连接关系。','A 是站点，A—B 是道路。'],['邻接矩阵','按顶点两两配对，用表格记录边或权重。','A 行 B 列记有路。'],['邻接表','每个顶点保存它直接相邻对象的清单。','A 的表为 B、C。'],['有向／无向','连接是否区分从哪边到哪边。','单行道有向，双向路可无向表示。']],
    'compare',[['同一张图','A—B，A—C'],['矩阵记录','A 与 B、C 的格子有边'],['邻接表记录','A:B,C；B:A；C:A']],
    [['先定义一条边到底表示什么','本例无向道路 A—B、A—C，各条可来回通行，B 与 C 没有直接路。路线图画得近不代表有边；必须由记录明确说明连接，权重还可以另记时间或费用。'],['矩阵把所有配对都留位置','三点用三乘三格。无向关系常在对应的两个方向都记录，例如 A,B 与 B,A 相同。没有边的标记不能和合法零权边混淆，带权最短路常需要另用无穷或存在性表示。'],['邻接表只列确实存在的连接','A 的表列 B、C，B 的表列 A，C 的表列 A。无向边通常在两个端点表里各出现一次，计数时不能因此认成两条独立道路；遍历邻居时则很方便。']],
    '三块是同一无向图的表示对照，表项不是有先后依赖的任务。','矩阵适合直接问某一对是否相邻，邻接表适合遍历邻居；重复边、自环与无边标记要由具体实现规定。');
  add('ds-bfs','像水波一圈圈扩开，怎么找到最少几步？','用队列和首次发现距离理解无权图最短路。',
    'A 通 B、C，B 与 C 又都通 D，每条路只算一步。从 A 出发，先把一步能到的 B、C 排队，再去考虑两步处的 D，像水波向外扩。BFS 用队列维持这层次：先被发现的近层先处理。记录“已经发现”还能防止 D 被两条路重复塞进队列。',
    [['BFS／广度优先','先处理离起点近的一层，再向外扩一层的搜索。','A 后是 B、C，再到 D。'],['距离','本课指最少经过多少条边。','A 到 D 为两步。'],['发现标记','某点入队时记作已发现，避免重复安排。','D 只入队一次。']],
    'layers',[['距离 0','起点 A'],['距离 1','发现 B、C 并入队'],['距离 2','通过 B 或 C 发现 D']],
    [['先给起点距离零','A 不必走路就已经在自己处，所以距离为零，标记后入队。取出 A 时检查直接邻居 B、C，把它们设为一，立即标记并排到队尾。'],['队列保证近层先展开','B 先出队时发现 D，距离为 B 的一加一步，即二。C 随后也能遇见 D，但 D 已发现，不再次入队；应在入队时标记，而不是等出队才标记。'],['首个发现路径为何够短','任何更少步数的路径都应来自更早处理的上一层，队列已经先展开了那些点，因此无权图中首次发现的步数最少。若道路费用不同，层数就不等于总费用最小。']],
    '无向边 A—B、A—C、B—D、C—D，所有边等成本；B、C 先后由邻居顺序决定。','BFS 得到的是无权或等权条件下的最少边数路径；非等权图不能直接拿首次发现当最便宜路线。');
  add('ds-dfs','一直沿路深入，走不下去再回来','把深入、已访问标记和回溯联系起来，避免把 DFS 当作最短路。',
    '在 A、B、C、D 的小图里，A 连 B 和 C，B 连 D，D 连 C。选择先去 B，就沿 A、B、D、C 一路深入，不能前进再退回最近的岔路。DFS 像沿一条小路探到底，访问标记防止遇到旧路时重复兜圈；它的发现顺序由邻居次序决定。',
    [['DFS／深度优先','优先沿一个尚未探索的分支深入，再回到分岔处继续。','A→B→D→C。'],['回溯','当前点没有新邻居后，返回上层继续检查。','C 走完后回 D。'],['发现／完成','发现是首次进入，完成是它所需分支都处理完。','进入和退出时刻可分别记录。']],
    'timeline',[['从 A 走 B','标记 A、B 已发现'],['继续到 D、C','遇旧点就跳过'],['走完逐层回','C→D→B→A 完成']],
    [['一进入就留下访问记录','从 A 开始，先选择 B，并在进入时标记已发现。无向边会指回刚来的 A，如果不检查标记就再次进入 A，搜索可能在同一条边两头反复走。'],['先深入，不立即处理所有同层','B 的新邻居为 D，D 再通 C，所以发现次序为 A、B、D、C。A 的另一个直接邻居 C 虽离它一步，却被深处分支先碰到，说明 DFS 层次不保证最短路。'],['没有新分支才完成返回','C 的邻居都已见过，标记完成后退回 D，逐层继续检查尚未尝试的邻居。发现和完成两个时机不同；分析有向边类型时不能只看一个“见过”标签。']],
    '无向图边为 A—B、A—C、B—D、D—C；假定 A 优先选 B。','递归栈或显式栈都可实现 DFS；遍历全图需要从尚未发现的点继续启动，而非只搜一个起点。');
  add('ds-connectivity-scc','能过去，和能来回，是两回事','用单向连接区分普通可达和强连通分组。',
    'A 与 B 可互相来回，C 与 D 也可来回，但只有一条从 B 去 C 的单向路。A 能到 D，不代表 D 能回 A。有向图的强连通要求一组内任意两点都能互相到达；因此这里应分成 A、B 与 C、D 两组，而不能因整张图连成一片就并作一组。',
    [['可达','沿方向允许的路径能从一个点到另一个点。','A 可经 B 到 C。'],['连通分量','无向图中能互相连通的最大分组。','同一组任意两点有路径。'],['强连通分量','有向图中任意两点可双向到达的最大分组。','A、B 一组，C、D 一组。']],
    'branches',[['组一 A、B','A↔B，可以互相回来'],['组间只有单向','B→C，没有返回通路'],['组二 C、D','C↔D，可以互相回来']],
    [['先把所有方向都保留下来','A↔B 表示两条相反方向的边，C↔D 同理。B→C 只有去路。把箭头擦掉再说连通，会回答另一个无向问题，不能用来判定原有向图的强连通。'],['逐对想有没有返回路径','A 能通过 B、C 去 D，但 D 只能在 C、D 内活动，没有回 A、B 的通路。一次 DFS 从 A 访问四点，只证明 A 可到它们，并不证明四点互相可达。'],['把互达最大组缩成整体','A、B 和 C、D 分别为强连通分量，缩成两个点后只剩组一到组二的箭头。一般强连通缩点图没有有向环，否则环上各组又会互达，应合成更大组。']],
    '组内双向连接，组间只有 B→C；这是连接关系图，不是算法执行的三次步骤。','此处只用小图辨概念；具体 SCC 算法还要维护完成顺序或栈状态，不能只按一次 DFS 的访问集合分组。');
  add('ds-topological-sort','先修课排顺序，谁现在可以开始？','用入度为零表示没有未完成前置条件，并发现有环时的障碍。',
    '任务 C 必须等 A、B 都做完，D 又必须等 C。A 与 B 谁先都可以，C 却不能只因为 A 完成就抢先开始。拓扑排序不断选择没有剩余前置条件的任务，完成后消去它造成的依赖。若还有任务却谁都等别人，可能形成了有向环。',
    [['有向无环图／DAG','边有方向且不存在沿箭头回到自己的环。','A→C→D，B→C。'],['入度','指向某点的边数；算法中统计尚未消去的前置边。','C 初始入度为二。'],['拓扑序','让每条依赖边的起点都排在终点之前的次序。','A、B、C、D。']],
    'flow',[['当前可做','A、B 入度为 0'],['两者完成后','C 入度 2→1→0'],['再完成 C','D 入度归零，可做']],
    [['先数清所有前置依赖','A、B 没有前置条件，所以入度零，可以任选其一。C 有 A、B 两条进入边，必须同时等待两个条件，不能把“存在一个前驱完成”误当成全部完成。'],['每做完一项才消去对应边','若先做 A，C 入度从二降一，仍不能做；再做 B，C 降零才进入候选集合。用队列或其他集合管理候选，不同选择可能得到不同合法拓扑序。'],['用完成数量检查是否卡环','C 完成后 D 可做，最终处理四个点。若候选为空却仍有未处理点，说明剩余依赖不能解开，有向环使全图拓扑序不存在；不是随便挑一个有入度的点继续就行。']],
    '依赖边 A→C、B→C、C→D；箭头表示前置任务，不是道路长度。','拓扑序只规定依赖先后，不直接计算任务时长或最早完成时间，也不要求所有合法序唯一。');
  add('ds-dijkstra','先确定最近那站，为什么后面不会改口？','在非负权条件下，用最小未确定估计逐步确定最短距离。',
    'A 到 B 直达花四分钟，A 到 C 一分钟，C 到 B 两分钟。从 A 看先给 B 估四、C 估一，最近的 C 先确定；经 C 再去 B 只花三，于是把 B 改为三。Dijkstra 每次挑未确定里最小的估计定下来，可靠性依赖后续路段费用非负。',
    [['边权','一条边对应的费用、时间等数值。','A→C 的边权为 1。'],['距离估计','当前已知可行路线的费用，不一定最终最短。','B 先为 4，后来改为 3。'],['松弛','尝试通过一个点绕行，若更便宜就更新。','1＋2＜4，更新 B。']],
    'timeline',[['A 确定为 0','估计 B:4，C:1'],['C 先确定为 1','经 C 把 B 更新到 3'],['B 确定为 3','直达 4 被更短路替代']],
    [['起点零，其余先未知','A 到自己费用零，沿 A 的边得到 B 四、C 一。估计是目前找出的真实路径成本，不表示第一次见到就已经最终定案；还需比较其他路径。'],['选择最小的未确定估计','C 的一小于 B 的四，先处理 C。经 C 到 B 的候选为一加二等于三，比四更小，所以更新 B。更新通常也记前驱，便于最后还原路线而非只有距离。'],['非负性支撑确定不回头','未来从更远的未确定点绕行，若每段都非负，不会突然比当前最小值更便宜。因此下一次可确定 B 的三；出现负边时，这个论证会断掉，不能继续照用结论。']],
    '有向边 A→B:4、A→C:1、C→B:2；所有边权非负。','基础 Dijkstra 要求相关边权非负；不可达点保持未知或无穷标记，不能当作一条实际长度为无穷的路线。');
  add('ds-bellman-ford','允许负费用后，还能反复把路线变便宜吗？','用有限边数的逐轮改进理解负边与可达负环检查。',
    'A 直达 B 费用四，A 到 C 费用五，C 到 B 费用负三，表示某段有返还；经 C 到 B 总费用只要二。负边本身不必让问题失效，但若能绕一个总费用为负的圈，反复绕就能一直变小，不存在有限最便宜值。Bellman-Ford 通过多轮检查边传播改进，并额外检查这种负环。',
    [['负边','费用小于零的边，不等于一定存在负环。','C→B 费用 −3。'],['松弛','用到达前点的已知距离加边权，尝试改善后点。','5＋(−3)＝2。'],['可达负环','起点能到的有向环，其边权和为负。','多绕一圈总费用继续减少。']],
    'timeline',[['至多一条边','B:4，C:5'],['至多两条边','经 C 令 B:2'],['额外检查','仍可改善则追查可达负环']],
    [['先给一步路线一个起点','A 为零，直达 B 得四，直达 C 得五。按逐轮使用上轮距离的解释，第一轮保证考虑至多一条边；不可达的点不能拿无穷标记随意参与减法制造假路线。'],['再允许多一条边传播改进','第二轮允许通过 C 接一段负三，总费用二，改善 B。一般无负环的有限最短路可去掉重复环，用至多顶点数减一条边，因此这么多轮足够传播所有必要路径。'],['更多轮仍下降意味着有问题','若在必要轮数后仍可从起点可达区域改进距离，要检查可达负环。负环会影响从它还能到达的点，并不自动使图中所有点都无有限最短路；范围需要分别判断。']],
    '有向边 A→B:4、A→C:5、C→B:−3；图用“上轮快照”的至多边数解释，未规定原地实现更新先后。','原地扫描可能在一轮传播多条边，仍可用相应证明分析；负环必须从起点可达，才影响该单源问题。');
  add('ds-floyd-warshall','逐个开放中转站，哪条路线会变短？','把经过新中转点与不经过它两种可能比较。',
    'A 到 C 直达要九，A 到 B 要二、B 到 C 要三。一开始只知道直达，后来允许把 B 当中转，就发现二加三只要五。Floyd 不是随便重复试路，而是规定一个阶段：现在允许哪些点做中转；每开放一个新点，就比较走它和不走它哪种更好。',
    [['全源最短路','计算每一对起终点之间的最短距离。','不只算从 A 出发。'],['中转点','路径起终点之外经过的中间顶点。','A→B→C 中 B 是中转。'],['阶段状态','记录只允许指定一批中转点时的最好距离。','先只直达，再允许 B。']],
    'compare',[['原候选','A→C 直达费用 9'],['新候选','A→B→C：2＋3＝5'],['取较小值','A 到 C 更新为 5']],
    [['先把直达信息准确初始化','对角线通常为零，有边记边权，无边记未知或无穷。零费用边是真边，不能把它与无边都写成零。这里 A 到 C 初值九，还没有利用 B 这个中转点。'],['只增加一个允许中转者','开放 B 时，从 A 到 B 的最佳费用二，加 B 到 C 的三，得五。路径不经 B 的候选仍为九，因此取较小值五；所有起终点对都要接受同样阶段的比较。'],['阶段顺序保证覆盖全部组合','核心中转点阶段放在外层，才能维持“已允许哪些中转点”的含义。若无可达负环，全部点开放后得到距离；对角线出现负值可作为负环线索，相关路径需另判。']],
    '有向边 A→B:2、B→C:3、A→C:9；图只放大其中一对起终点的更新。','不要把三个循环任意换序后仍宣称同一递推。无穷标记相加需防溢出，负环影响范围也不能忽略。');
  add('ds-prim','铺网线省总价，先长出一棵连通树','从已连好区域向外选最便宜跨界边，而不是寻找某条最短路。',
    '三栋楼 A、B、C 要全部接通：AB 费用一，AC 四，BC 二。从 A 开始先接最便宜的 AB，再从已接的 A、B 向外看，接 BC 比 AC 更省，总价三。Prim 每次扩张一片已经连通的区域；目标是整张网络总价低，不是保证 A 到每栋楼的路线都最短。',
    [['生成树','包含全部顶点、连通且没有环的一组边。','三点只需两条接通。'],['最小生成树','在同样接通全部点的生成树中，边权总和最小。','AB、BC 合计 3。'],['跨界边','一端在已连区域、一端在外面的边。','接上 B 后，AC、BC 跨界。']],
    'timeline',[['已连区域 A','候选 AB:1、AC:4'],['接入 B','选择 AB:1'],['接入 C','选 BC:2，总价 3']],
    [['先给连通区域一个起点','从 A 开始，区域内只有 A，查看向外的 AB 和 AC，选费用一的 AB。起点可以不同，但必须按跨界条件选边，不能把两端都在区域外的便宜边直接算作本轮扩张。'],['每加一点都重新看整片边界','接上 B 后，区域是 A、B，因此候选包括 A 到 C 的四和 B 到 C 的二。选二把 C 接入，不能只看刚加入点的某一条边，也不应把已在区域内的环边再接一次。'],['确认目标是总价而非路径距离','两条边总价一加二等于三，三点全部接通且无环。Prim 与 Dijkstra 都会反复选小值，但此处的小值是跨界边费用，不是从起点累计的距离，更新意义不同。']],
    '无向连通三角形：AB=1、AC=4、BC=2；图展示从 A 开始扩张。','最小生成树用于无向图；图不连通时不存在覆盖全部点的一棵生成树，可分别求最小生成森林。');
  add('ds-kruskal','把便宜的线先买下来，怎样避免接出圈？','按边权排序，只接通原本不同的连通组。',
    '四栋楼有 AB 一元、BC 两元、AC 三元、CD 四元的连接选择。按便宜顺序买 AB、BC 后，A、B、C 已经互通，再买 AC 只会绕个圈，应该跳过，转买 CD 把 D 接入。Kruskal 不从一片区域长大，而是允许多个小组逐步被便宜边合并。',
    [['按权排序','按每条边费用从小到大考察。','1、2、3、4。'],['连通组','当前已经由所选边接通的一组点。','选 AB、BC 后 A,B,C 同组。'],['判环','检查加入某边会不会形成圈。','同组的 A、C 再接就有环。']],
    'timeline',[['先选 AB、BC','两边费用 1、2'],['跳过 AC:3','A、C 已属同一组'],['再选 CD:4','四点接通，总价 7']],
    [['边的顺序按费用，而非起点','把所有候选边按权从小到大排序，初始每点各自成组。先看 AB、再 BC，它们的两端原本分属不同组，所以选入并合并，保留无环森林。'],['两端同组就已经有路','考察 AC 时，已有 A—B—C 的路径，再加 AC 就闭成环，故跳过。即使它还比某些未选边便宜，也不能为凑便宜无视无环要求。'],['跨不同组才使网络进展','CD 把大组 A,B,C 和单独 D 合并，选择它后四点接通，边数三。常用并查集快速查两端是否同组；停止和不连通检测也要按点数与边数检查。']],
    '无向图四点，边 AB:1、BC:2、AC:3、CD:4；所选总权为 1＋2＋4＝7。','等权边可以有多种选择和多棵同价最小树；排序相同不意味唯一答案，图不连通时只能得到森林。');
  add('ds-aoe-critical-path','项目要多久，为什么得等最慢的前置工作？','用两条工序路线比较最早完成与零余量活动。',
    '从开始 A 到 B 的工作需三天，A 到 C 两天；B 到结束 D 四天，C 到 D 一天。两条路线可并行，但 D 必须等相关前置都完，最早要七天，不是把所有工期加成十天。关键路径找的是决定项目下限的最长依赖路线，延误其上工作会推迟整体。',
    [['AOE 网','用顶点表示事件、带时长的有向边表示活动的依赖图。','A→B 三天是一项活动。'],['最早事件时间','所有前置条件都满足后，某事件最早能发生的时刻。','D 要等两条路线，取较晚的七天。'],['余量／关键活动','可延迟而不改变计划总工期的空间；余量零的是关键活动。','A→B、B→D 在此例为关键。']],
    'branches',[['路线 A→B→D','3＋4＝7 天'],['路线 A→C→D','2＋1＝3 天'],['共同结束 D','最早 max(7,3)＝7 天']],
    [['把活动与事件分开','边上的三天代表做活动所需时长，A、B 等点表示事件达到而不是又花一段工时。先确认依赖图无环，按拓扑顺序传播，否则不能简单按项目先后计算。'],['汇合点必须等全部前置','B 最早第三天，C 最早第二天；两条到 D 的完成候选为七和三。D 取最大值七，因为必须同时满足前置，不能为了“最早”就误取最小的三。'],['倒推最晚时间再比较余量','为不超过七天，倒推各事件的最晚允许时刻，再比较每条活动最早与最晚开工差。零余量活动组成关键路线；如果有多条关键路径，只缩短其中一条未必缩短整个项目。']],
    '有向无环 AOE 图：AB:3、AC:2、BD:4、CD:1；假设依赖允许的活动可并行且资源不限制。','关键路径法不自动处理人手、设备冲突和随机工期；现实资源限制会增加约束，不能只按本图承诺完成日期。');
  add('ds-union-find','只合班、不拆班，怎么快速问是不是同组？','用代表节点维护分组，区分查代表与真的查路径。',
    '四位同学最初各一组，先把 A、B 合组，再把 C、D 合组。现在问 A 与 D 是否同组，只需各找所属组的代表；把 B 与 C 的组合并后，四人就同组了。并查集保存的是分组关系，不是完整友谊路线，适合很多“不断合并、不断询问”的任务。',
    [['集合代表','用来标识当前分组的根节点，不具有永久业务意义。','A、B 的组可能以 A 为代表。'],['find','沿父连接找到当前代表的操作。','比较 find(A) 与 find(D)。'],['union','把两个不同组接成一个组。','合并 AB 组与 CD 组。'],['路径压缩','查代表后把经过节点更直接地接近根。','下次查同组少绕路。']],
    'timeline',[['开始四组','A｜B｜C｜D'],['两次合并','AB｜CD'],['再合并 B、C','ABCD 成为一组']],
    [['每组先给自己一个入口','初始每个节点是自己的代表。合并 A、B 时，找到两个根，再按大小或高度等规则接起来；不应随便把任意内部节点相连，造成环或损坏代表关系。'],['同组由代表是否相同决定','合成 AB 与 CD 两组后，A 和 B 的 find 相同，A 与 D 的 find 不同。代表字母不必永远相同，结构优化可能改变根，但不应改变“谁与谁同组”的逻辑。'],['只维护分组，不保留全路径','再合并 B、C 实际合并它们的两个根，四人同组。路径压缩可改父连接让查找更快，因此父边不是原图所有真实边，不能拿它回答原图两点的具体路线。']],
    '竖线表示当前不同组；组名只作集合成员展示，不表示内部父树的唯一形状。','标准并查集擅长合并与同组查询，不支持随意拆分；近乎常数的均摊结论需要配合相应压缩与合并策略。');
})();
(() => {
  const target = window.PLAIN_BEGINNER = window.PLAIN_BEGINNER || {};
  function add(id, plainTitle, goal, story, terms, kind, nodes, steps, caption, boundary) {
    target[id] = { plainTitle, goal, story,
      terms: terms.map(([word,meaning,example])=>({word,meaning,example})),
      diagram:{kind,nodes:nodes.map(([name,detail])=>({name,detail})),caption},
      steps:steps.map(([title,text])=>({title,text})),boundary };
  }
  add('ds-adt-structure','先说要做什么，再说放在哪里','分清数据关系、使用规则和机器里的存放方式。',
    '你要管理三位同学的成绩：能查第几位、能加一位、能删一位。先说清这些要求，不必立刻决定把成绩排进连续格子，还是用箭头串起来。数据结构先讨论信息怎样组织、要做哪些操作，再选择放进机器的具体办法。同一套使用要求可以有不同实现。',
    [['数据元素','作为一个整体处理的一份信息。','一位同学的一条成绩记录。'],['逻辑结构','数据之间在问题里的关系，不等于内存位置。','甲排在乙前面。'],['存储结构','在机器里保存数据及关系的方式。','连续格子或带箭头的节点。'],['ADT','抽象数据类型：先规定数据及操作应怎样表现。','栈规定最后放入的先取出。']],
    'layers',[['需要的操作','查、加、删成绩'],['操作契约','合法输入与应得结果'],['具体存放','可选数组或链表']],
    [['先列动作','先写“读第 i 项”“尾部加一项”等具体动作，再说明空表和非法下标怎么办。这是从使用者角度规定行为，暂时不用考虑某一格内存怎么分配。'],['把规则与零件分开','若规定最后加入的必须最先取出，这就是栈的规则。你可以用连续格子做，也能用连接节点做；符合相同行为的实现，不必具有相同存储外观。'],['根据常做的事选实现','经常按下标直接读，数组值得考虑；经常修改已知位置附近的连接，链表可能合适。还要算寻找位置的成本，不能只看到“插入”就断定链表一定快。']],
    '三层是“需求—规则—实现”的关系，不是程序运行时必经的三站。','本图比较组织层次。具体效率还取决于规模、实现与已知信息，不存在任何操作都最优的结构。');
  add('ds-asymptotic','数据多十倍，工作会多多少？','把输入数量与操作次数联系起来，读懂上界、下界和同阶。',
    '整理 10 张卡片和整理一万张卡片，难处不只是“电脑快不快”。如果每张只看一次，卡片多十倍，工作大约多十倍；如果每张都和其他每张比较，工作可能接近平方增长。复杂度就是先数工作随规模怎样增长，再暂时忽略固定倍数比较趋势。',
    [['n','用来表示输入规模的字母，必须说明数什么。','本题 n 是卡片张数。'],['O','渐近上界：足够大后，工作量不超过某个固定倍数的增长式。','3n＋2 是 O(n)。'],['Ω','渐近下界：足够大后，工作量至少达到某个固定倍数的增长式。','3n＋2 是 Ω(n)。'],['Θ','上下界同阶，较准确地指出主要增长速度。','3n＋2 是 Θ(n)。']],
    'compare',[['逐项查看','n 项，大约看 n 次'],['两两查看','可能接近 n² 次'],['比较增长','先固定所数的操作']],
    [['先说清数的是什么','若任务是把每张卡片检查一次，就把“检查一张”当作一次基本操作，n 当作卡片数。操作总数可以是 3n＋2，并不是一写 O(n) 就宣称恰好只做 n 次。'],['把大小规模放在同一规则下','n 增加十倍，线性项增加十倍，平方项则增加一百倍。小输入时常数可能占主要影响，因此一次测量快慢不能替代大规模增长的判断。'],['给符号配上中文','O 说不超过某种增长的固定倍数，Ω 说至少，Θ 说两边都能夹住。它们不分别代表最坏、最好、平均；应先指定哪种输入情况下的工作量再讨论界。']],
    '这是不同增长规则的对照，不是排序过程；n² 表示 n 乘 n。','把基本操作视为固定成本是分析假设。若一次操作处理越来越长的字符串，必须把内部成本也算入。');
  add('ds-loop-counting','重复两层，就一定平方次吗？','列出每轮真实次数，再决定相加、相乘还是数翻倍。',
    '排椅子时，四排各有四把，一共十六把；若每排分别只有一、二、三、四把，就只有十把。两种都有“先选排、再选椅子”两层动作，但工作量不同。分析循环也要看每轮实际做多少次，而不能只数代码里有几个 for 或 while。',
    [['循环','满足条件时重复执行一组动作。','依次处理四排椅子。'],['嵌套','一个重复过程内部又有重复过程。','每选一排，再数这一排。'],['求和符号 Σ','把指定范围内的各项加起来。','1＋2＋3＋4＝10。'],['log₂n','二不断翻倍到 n 附近所需的次数量级。','1→2→4→8 只翻倍三次。']],
    'timeline',[['第一轮','内层执行 1 次'],['后续各轮','再执行 2、3、4 次'],['合计','1＋2＋3＋4＝10']],
    [['先代入小输入','设外层编号从 1 到 4，每轮内层执行外层编号那么多次。第一轮只执行一次，不能因为外层上限是 4 就把每轮都算成四次。先列次数最容易看出差别。'],['看变量是否重新开始','各轮的内层次数依次为 1、2、3、4，应加起来。若内层指针没有重新置回开头，还可能把多轮工作共享；即使代码看起来嵌套，也不一定重复扫描。'],['最后写一般式','本题 n 轮合计 1 到 n，等于 n(n＋1)÷2，是平方增长。每轮把变量翻倍则要改数翻倍几次，不能再用同一个求和式；初值、更新、终止条件都要看。']],
    '图展示 n＝4、内层每轮执行 i 次的三角形计数。','小输入用于发现规律与边界，最终增长阶仍需一般式或上下界论证，不由一两次试跑证明。');
  add('ds-cases-average','找同一个东西，为什么次数不同？','区分最好、最坏和有条件的平均次数。',
    '在按顺序摆好的五张无序号码卡里找 8。如果第一张就是 8，只看一次；若最后一张才是 8，就要看五次；若根本没有，也得查完整排。算法没换，输入摆放却改变工作量。“平均快”还必须说明每种摆放怎样出现，不能把最好和最坏随便取中间。',
    [['最好情况','同规模允许输入中，用工作最少的情况。','目标在第一张，只比一次。'],['最坏情况','同规模允许输入中，用工作最多的情况。','目标不存在，要看完。'],['平均情况','按指定概率分布对工作量加权平均。','成功且五个位置等可能。']],
    'compare',[['第一张命中','比较 1 次'],['第五张命中','比较 5 次'],['等可能成功','平均 (1＋…＋5)÷5＝3']],
    [['固定同一种算法与规模','这里都用从左向右逐张查找，卡片数固定为五。目标碰巧在开头只比一次，不表示该算法在任何输入上都只比一次，也不表示程序完成了跳跃查找。'],['把最慢的合法输入想出来','目标在末尾或根本不存在，都需要逐张排除前面的候选。本题最多五次，所以最坏次数是五；“最坏”描述输入条件，不等于写下 O 符号本身。'],['平均前先说概率','若已知一定找得到，且五个位置等可能，平均次数才是 3。若找不到很常见，或开头位置更常出现，平均值就会变化，不能沿用这个数字。']],
    '三种情况并列比较；平均值依赖“成功且各位置等可能”的假设。','平均情况讨论随机输入分布；均摊分析讨论一串操作的总成本，两者不是同一件事。');
  add('ds-amortized','偶尔很贵的一次，为什么平均还能便宜？','用多次追加的总搬运次数理解均摊，而不是把它当成概率。',
    '笔记盒装满才换成两倍大的盒子。平常加一张纸只需放进去，换盒时却要搬走旧纸，看起来某次特别慢。但从空盒连续加很多张，每张旧纸不会在每次添加都搬一遍。均摊分析就是把整串操作的总费用算完，再分给每次操作看，而不是赌扩容“出现概率低”。',
    [['动态数组','需要时另找更大连续空间保存元素的数组实现。','容量从 1 增到 2、4、8。'],['扩容','现有容量不够时增加可用空间。','三项放不进容量 2 的盒子。'],['均摊成本','把一串操作的总成本分摊到各次操作的分析值。','偶尔搬运不会让每次都线性。']],
    'timeline',[['容量 1→2','搬旧元素 1 个'],['容量 2→4','再搬 2 个'],['容量 4→8','再搬 4 个']],
    [['先承认某一次可能很慢','容量满时添加新元素，需要申请更大区域并搬运现有元素。若已经有 n 个元素，这一次可能搬 n 个，所以单次最坏成本不能说永远是常数。'],['再把整串搬运相加','从容量 1 逐次翻倍到 8，共搬 1＋2＋4＝7 个旧元素。加上每个新元素原本的一次写入，连续八次追加的总工作仍只与八成固定倍数关系。'],['用总费用得到均摊结论','一般翻倍扩容的旧搬运形成 1＋2＋4…，合计小于最后容量的两倍，因此连续追加总成本是线性，均摊每次为常数。若每次只多一个容量，就不是这个结论。']],
    '图只列三次实际扩容的搬运量；中间无需扩容的追加不搬旧元素。','此结论针对按固定比例扩容及规定的操作串；均摊常数不承诺每次延迟都小，实时任务仍要关注最坏一次。');
  add('ds-space-analysis','除了输入本身，还偷偷占了多少地方？','区分输入空间、辅助空间与递归等待记录。',
    '把一副牌就地整理，只用一张临时便签；另一个办法要再拿一副同样大小的空牌槽。它们处理同一份输入，额外用的地方却不同。分析空间时先说明是否计入原输入，再看临时数组、函数等待记录和输出。代码没写“新建数组”，也可能因递归层层保留状态而占空间。',
    [['辅助空间','完成算法时，输入本身之外额外需要的工作空间。','一份临时数组。'],['原地算法','按所用约定，仅需很少额外工作空间的算法。','只用少量变量交换元素。'],['递归栈','未返回的函数调用需要保留的状态。','每层等下一层先算完。']],
    'layers',[['输入 n 项','待处理的数据本身'],['额外数组 n 项','辅助空间随 n 增长'],['调用深度 d','还需保留 d 层状态']],
    [['先规定哪些东西算进来','若题目问辅助空间，就不把原输入数组算成新开销，但临时副本一般要算。输出是否计入也要先说明，否则两份答案可能只是在不同口径下统计。'],['找会随输入增长的工作区','固定几个计数变量通常视为常数额外空间；开一份 n 项临时数组则随 n 线性增长。不是变量名字少就一定省空间，一个变量也可能指向很大的数组。'],['把未返回调用也画出来','递归若同时保留 d 层、每层固定大小状态，额外栈空间随 d 增长。两个子问题先后递归时，要看同时存在的最大深度，不把所有历史调用一律相加当峰值。']],
    '三层是空间来源对照；d 为同时尚未返回的最大调用层数。','本课通常按普通字长变量为固定大小统计；若对象本身是增长的大整数，还要细算表示空间。');
  add('ds-structure-selection','选数组还是链表，先问哪几个问题？','从操作频率和位置是否已知出发比较候选结构。',
    '学生名单每天查询第几个人，偶尔在末尾加人；另一份任务清单却经常在已找到的节点后加任务。两件事都叫“保存列表”，合适的实现可能不同。选择结构不是给名字排名，而是先把常做的动作、数据量和限制列出来，再比较每种实现为这些动作付出的代价。',
    [['随机访问','知道下标后直接定位某一项，不必走过前面各项。','数组读取第 50 项。'],['前驱节点','在链上指向目标位置的前一个节点。','甲→乙，甲是乙的前驱。'],['操作频率','某种操作在使用中出现得多不多。','每天查询一万次、插入两次。']],
    'branches',[['列出使用情况','读下标多，还是改连接多'],['数组候选','直接定位；中间可能搬移'],['链表候选','改连接快；找位置可能慢']],
    [['先把问题写成动作表','例如“按下标读取一万次、尾部追加两次”，比“我要一个高效列表”更能帮助判断。还要记录是否已知位置、容量是否稳定、是否需要保持有序。'],['计算数组真正要做的事','按下标定位通常能直接算地址；中间插入则要把后面的元素腾位置。若只是尾部追加，还要问容量够不够，扩容成本和普通追加不能混成一种。'],['计算链表真正要做的事','已知前驱时，插入可只改少量连接；若只给第 50 个位置，仍需先顺链找过去。把找位置和改连接相加，才是使用者实际付出的整次操作成本。']],
    '分支图是候选方案比较，不表示必须先执行数组操作再执行链表操作。','实际还受缓存、内存开销、线程与接口约束影响；课内量级分析用于筛选，不代替对真实负载测量。');
  add('ds-array-storage','为什么数组能一下找到第几个？','用起点、下标和元素大小算出地址，并检查范围。',
    '电影票座位编号规则固定，知道一排从哪里开始、每个座位隔多远，就能直接找第几个。数组把同类型元素连续摆放，也是这个道理。若三个整数从 1000 开始，每个占四字节，它们起点就是 1000、1004、1008；下标只负责说明跨过几个元素。',
    [['顺序存储','把逻辑相邻元素放在连续的存储区域中。','三个四字节整数连续排列。'],['基址','作为起点的地址。','首元素地址为 1000。'],['下标','元素的编号，C 从 0 开始。','下标 2 是第三个元素。'],['容量与长度','容量是可放多少，长度是现在实际有多少。','容量 8、现有 3 项。']],
    'memory',[['下标 0','地址 1000'],['下标 1','地址 1004'],['下标 2','地址 1008']],
    [['先把一个元素多大写清','本图假定每个整数占四字节，所以相邻元素起点相差四。实际类型大小应按平台或题目条件确定，不能看到“下一个”就一律把地址增加一。'],['把下标换成跨过的距离','下标 2 表示跳过前面两个元素，偏移是 2×4＝8 字节；加起点得 1008。定位不需要先读取前两个元素，这就是已知下标可直接定位的原因。'],['算得出地址不代表可以访问','长度为三时合法元素下标为 0、1、2。下标 3 也能算出一个数值地址，却不是这三项里的合法元素；检查范围要在读取或写入前完成。']],
    '地址是教学编号；图只表示三个元素的起点，每个元素实际占四个字节。','数组直接访问指已知合法下标后的定位成本，不包括另行查找某个数值在哪，也不自动检查 C 代码边界。');
  add('ds-sequential-edit','在中间加一个数，为什么要从后往前搬？','在 2、5、8 中插入 4，理解怎样搬移才不覆盖未搬的数据。',
    '桌上三张卡依次写着 2、5、8，想在 5 前面插入 4，最右边还有空位。若先把 5 覆盖到 8 的位置，原来的 8 就没了。应该先搬最右边的 8，再搬 5，最后放 4。数组中间插入也是给后缀腾位，搬动方向是保护还没处理数据的关键。',
    [['插入位置','新元素要占的编号位置。','在下标 1 放入 4。'],['后缀','从某个位置一直到末尾的那段元素。','本例 5、8 需要右移。'],['删除压紧','删掉一项后，让后续元素向左补空位。','删 5 后把 8 搬过来。']],
    'timeline',[['原来','2、5、8、空'],['先搬后面','先移 8，再移 5'],['放入新数','2、4、5、8']],
    [['先确定有空位与合法位置','当前三项，插入后要四项，因此先检查容量至少为四。插在下标 1 意味着原来的 5 和 8 都要后退一格；只修改长度数字不能真的腾出位置。'],['从最右边开始保护旧值','先把 8 从下标 2 复制到 3，再把 5 从 1 复制到 2。这样每次目标格都已经安全空出来。若从左向右搬，可能把还没读出的 8 覆盖掉。'],['最后填空位并更新长度','下标 1 腾空后才写入 4，长度由三变四。删除时方向相反：从删除点后方逐项向左补，再减少长度；不要保留两个方向相同的机械口诀。']],
    '这是插入过程的三个时刻，数组必须已预留第四个位置。','本图按可直接赋值的小元素说明搬移；涉及对象构造、重叠复制接口时，还需遵守对应语言及库规则。');
  add('ds-dynamic-array-growth','换了更大盒子，旧门牌还能用吗？','把扩容理解成可能换位置，区分元素顺序与地址稳定性。',
    '两格盒子里装着 7、9，现在要追加 12。若旁边没空位，系统可以另找四格盒子，把 7、9 搬过去，再放 12。你看见的顺序没变，旧盒子的门牌却不能继续当作新元素的位置。动态数组给人“会长大”的感觉，背后可能是换了一整块区域。',
    [['扩容','容量不足时获得更大可用区域。','两格变四格。'],['长度','当前实际保存的元素数。','追加前 2，追加后 3。'],['地址失效','原先记录的位置不再保证指向原对象。','搬走后不能继续使用旧元素指针。']],
    'flow',[['旧区域','容量 2：7、9'],['新区域','容量 4：搬入 7、9'],['完成追加','7、9、12、空']],
    [['先检查容量而非只看长度','长度是当前两项，容量也是两项，因此没有合法的第三个位置。追加前必须先增加容量，不能把第三项直接写到盒子外，再希望它自动变成自己的空间。'],['新区域可能在别处','找四格区域后，把有效的旧元素依次迁移过去。元素次序保持，但物理位置可以变；缓存的元素地址、迭代器或引用是否失效，要按所用容器的规则处理。'],['用新的起点继续工作','更新数组的起点和容量，再写入 12 并增加长度。使用者若需要长期标记某项，可以考虑保存下标或稳定标识，但中间插删也可能改变下标，仍须明确标识语义。']],
    '箭头表示可能发生的迁移；并不承诺扩容每次都能在原地址向后延伸。','具体指针与迭代器失效规则由语言和容器决定；本图解释常见迁移机制，不把所有库接口一概而论。');
  add('ds-sentinel-list','一个箭头接一个箭头，怎样找到第一项？','区分链表节点、头指针与不存业务数据的头哨兵。',
    '寻宝纸条并不挨着摆，每张只告诉你下一张在哪里。先拿到第一张的位置，再按箭头寻找，这就像单链表。为了让“在第一个前面插入”也能像其他位置一样处理，常先放一张不算正式数据的引导纸条，叫头哨兵。它帮忙接线，但不是名单中的第一位同学。',
    [['节点','保存一个数据和连接信息的对象。','节点里有 7 和下一节点地址。'],['头指针','保存链表入口位置的变量。','由它找到入口节点。'],['头哨兵','放在首个数据节点前的辅助节点，不计业务项数。','空表时它也可能存在。'],['next／空指针','next 记录下一个节点；空指针表示没有下一节点。','尾节点 next 为空。']],
    'flow',[['头指针','指向入口哨兵'],['头哨兵','不算数据，next→7'],['数据节点','7→9→空']],
    [['先找到入口而不是猜地址','链表节点可以散放，不能像数组那样用起点加固定距离跳到第十个。头指针提供入口，接下来靠节点里的 next 逐个走；位置与里面的数值要分开。'],['给最前面也配一个前驱','头哨兵没有业务数据，却提供稳定的前驱位置。插入首元素时只需在哨兵后接上新节点，和在普通节点后插入类似；不能因此把哨兵也算进数据长度。'],['沿连接走到结束标志','数据节点 7 指向 9，9 的 next 为空，才表示到尾端。空的带哨兵链表可以只有哨兵且 next 为空；头指针不为空并不能直接说明有正式数据。']],
    '本图采用“有头哨兵”的约定；不带哨兵的实现入口直接指向首数据节点。','头结点、头指针的教材用词可能不同，读代码先确认约定；空表条件不能从另一种实现照搬。');
  add('ds-doubly-circular','有来回箭头，删除会多改哪些线？','理解前后连接和首尾相接的约定，删除后检查两侧关系。',
    '三位同学排队，每人既知道前面是谁，也知道后面是谁，就能向前或向后走，这像双向链表。若再让最后一个知道第一个、第一也知道最后一个，就成了循环结构。多几条线让某些动作方便，却也多几条必须维护的关系：删掉中间那位，前后两边都要接好。',
    [['双向链表','每个节点通常记录前驱和后继两种连接。','A⇄B⇄C。'],['prev／next','分别指向前一个和后一个节点的连接字段。','B.prev 指 A，B.next 指 C。'],['循环链表','末端通过约定连接回入口，不靠普通尾部空连接结束。','C 的后继回到 A。']],
    'compare',[['删除前','A⇄B⇄C'],['接好前方','A.next 改指 C'],['接好后方','C.prev 改指 A']],
    [['先读取被删节点两侧','要删 B，先知道左侧 A 和右侧 C。这个例子已给 B 的位置，因此可以直接取它的 prev 和 next；若只给数值，寻找 B 的步骤仍需另外计算。'],['一条前进线不能代替两边连接','先让 A.next 指向 C，此时从前往后绕开了 B，但 C.prev 还可能指着 B。若忘改后向连接，正着看似正常，倒着走却可能触及已删除节点。'],['回查首尾与空结构约定','把 C.prev 改为 A 才接齐两边。若是循环表、带哨兵表或删除唯一元素，边界表现各不相同；按当前实现逐条检查，不要假定一定遇到空指针结束。']],
    '图展示普通中间节点删除的先后检查；循环关系应按所采用的哨兵约定另行闭合。','双向表已知节点时便于删除，但增加存储和维护工作；并发访问还需同步，本图只讨论单线程连接。');
  add('ds-list-reverse-merge','反转箭头前，为什么先记住后面的路？','用 1→2→3 追踪反转，并理解两个有序链表的头部归并。',
    '沿 1→2→3 前进时，如果立刻把 1 的箭头倒回去，通往 2 的路就可能丢了。反转链表要先把后面的入口记到临时位置，再改当前箭头，最后整体前进。归并则是另一种保护路的工作：两条已经有序的链，每次从两边头部挑小的接入结果，未处理部分仍须保持可达。',
    [['反转','让原来的后继关系改成逆方向。','1→2→3 变为 3→2→1。'],['前驱 prev','反转过程中已经处理部分的新入口。','先由空开始。'],['当前 cur／后继 next','cur 是正在处理的节点，next 暂存原来的下一站。','改箭头前记住 2。'],['归并','把两个已按同规则排好序的序列合成一个有序序列。','1→4 与 2→3 合成 1→2→3→4。']],
    'timeline',[['先保存后继','当前 1，记住后面是 2'],['再反转当前','1 的 next 改指前驱'],['最后共同前进','前驱移到 1，当前移到 2']],
    [['先为未处理部分留入口','开始前驱为空，当前为 1。先记住 1 原来指向的 2，之后即使改掉 1.next，仍有办法找到未处理的 2→3。保护信息必须发生在破坏旧连接之前。'],['只改当前这一条线','让 1.next 指向已处理部分入口，也就是目前的空。当前节点成为反转好的一段。此时仍没有完成整表，不能把“这一条箭头改了”误当作入口也自动更新。'],['推进三项角色并重复','前驱变 1，当前用暂存后继变 2，重复直到当前为空。归并时同样先记清两条未处理链入口，每次只接较小头节点，保证剩余节点没有被接线丢失。']],
    '图是反转的一轮；归并是另一算法，正文说明共同的“不丢未处理入口”原则。','链表反转假设没有共享节点或环；归并假定两条输入已排序且结构合法，不应无检查地把带环链接起来。');
  add('ds-invariants-in-practice','怎么保证做到一半也没有弄丢数据？','用分区与连接不变量检查有序去重和链表逆置。',
    '整理卡片到一半，左边说“已经整理好”，右边说“还没处理”。如果每一步都能保证这句话仍为真，就不会只在最后碰运气。算法里的不变量就是这种阶段承诺。有序去重可承诺“前面已保留的都互不重复”，链表反转可承诺“已反转与未处理两段仍都找得到”。',
    [['不变量','开始成立、每步维持的一条阶段性质。','已处理前缀没有重复。'],['读位置','检查下一个原元素的位置。','逐个读 1、1、2。'],['写位置','下一项要保留的数据应写到的位置。','重复项不增加写位置。']],
    'flow',[['读第一项 1','保留区变成 1'],['读重复的 1','跳过，保留区不增长'],['读新值 2','接入，保留区为 1、2']],
    [['先把输入条件写出来','对有序序列 1、1、2，相同值相邻，因此与上一个保留值比较就能识别重复。输入若无序，这个判断不够；必须先排序或改用其他记录方法。'],['用读写位置守住两个区域','读位置看下一个原值，写位置只在发现新值时增长。处理第二个 1 时不写入新位置，保证保留前缀仍无重复；写位置不跑到读取进度前面，避免覆盖未读数据。'],['用同样办法检查接线算法','链表逆置虽没有连续下标，也能划分已处理和未处理。每轮先保存后继，确保两部分入口存在，再改箭头。最后还要看终止条件，确认“已处理”最终覆盖所有输入。']],
    '图追踪有序输入 1、1、2 的三次读取；保留区表示逻辑有效前缀，并非自动缩小物理容量。','不变量不是一句空泛的“算法正确”，需要能在每一轮具体检查，并与终止条件一起推出最终目标。');
})();
(() => {
  const target=window.PLAIN_BEGINNER;
  function add(id,plainTitle,goal,story,terms,kind,nodes,steps,caption,boundary){target[id]={plainTitle,goal,story,terms:terms.map(([word,meaning,example])=>({word,meaning,example})),diagram:{kind,nodes:nodes.map(([name,detail])=>({name,detail})),caption},steps:steps.map(([title,text])=>({title,text})),boundary};}
  add('ds-tree-terms-properties','从一个根分叉，树的名字各指哪里？','在具体树上认出根、孩子、叶子和层，区分完全与满。',
    '把学校组织画成校长往下分部门、部门再分小组的图，每个下级只接一个直接上级，就接近一棵有根树。先拿 A 为根、A 下接 B 和 C、B 下接 D 的小图认位置。名字并不表示人更重要，而是描述连接关系。二叉树则把每个位置的孩子最多限制为左右两个。',
    [['根／孩子','根没有父节点；直接往下一层连接的节点是孩子。','A 为根，B、C 是 A 的孩子。'],['叶子／度','没有孩子的是叶子；节点的度是孩子个数。','C、D 为叶子，A 的度为二。'],['完全二叉树','除末层外填满，末层位置从左连续占用的二叉树。','最后一层不能跳过左位先放右位。']],
    'layers',[['第 1 层','根 A'],['第 2 层','A 的左 B、右 C'],['第 3 层','B 的左孩子 D']],
    [['先从入口确定相对关系','本例选 A 为根，B 的父节点为 A，D 的父节点为 B。父子是直接相连，祖先则可以隔多层；不能把所有在上方的节点都称为直接父节点。'],['把孩子数与路径长度分开','A 有两个孩子，所以度为二；D 没有孩子，是叶子。度不是层数，也不是从根走来的边数。教材把根层从零或一开始都可能，本图明确从第一层编号。'],['检查末层有没有靠左填','图中前三层的已有位置靠左连续，所以是完全二叉树，但不是每层都满的满二叉树。二叉树只限孩子数最多二，不自动要求左右一样高或每层占满。']],
    '连接关系是 A→B、A→C、B→D；层次块表示分层而不是额外的节点。','“满二叉树”一词在不同资料可能指全满或每内部点恰有两个孩子；本课按原教材约定读正式定义。');
  add('ds-tree-storage','树画得很省，为什么数组里却有很多空格？','比较编号位置与连接存储，理解倾斜树会浪费顺序位置。',
    '把二叉树节点按完全二叉树的位置编号，根放 0，左孩子放 1，右孩子放 2，就能由下标算出关系。但若每个节点都只向右长，位置会到 0、2、6、14，只有四个节点却跨了十五个位置。另一办法给每个节点记左右孩子的地址，只为真实节点留记录。',
    [['顺序存储','按固定树形位置编号把节点放入数组。','根下标零，孩子为 2i＋1、2i＋2。'],['链式存储','节点记录孩子位置，通过连接表达树形。','left、right 可为空。'],['空位置','编号规则要求但实际上没有节点的槽。','只有右孩子时左槽空着。']],
    'compare',[['右斜树路径','A→右 B→右 C'],['数组位置','分别是 0、2、6'],['连接节点','只为 A、B、C 留记录']],
    [['先按零起始规则编号','根在下标 0，节点 i 的左孩子位置为 2i＋1，右孩子为 2i＋2。由此 A 的右孩子 B 在 2，B 的右孩子 C 在 6，跳过的位置不能随意挤掉。'],['稀疏形状会留下大量空槽','虽然本例只有三个节点，顺序编号仍涉及 0 到 6 的范围。继续一直向右，跨度增长很快；编号方便不意味着任何形状都节省空间。完全二叉树则通常能把位置填得紧凑。'],['用真实连接表达不规则形状','链式节点可记录左、右孩子的地址，不存在的孩子用空连接表示。它省去许多位置空洞，却为连接增加开销，也不能只凭下标直接找到某个结构位置。']],
    '三块是同一棵右斜树的两种保存方式对照，不是 A、B、C 的一条数组连续布局。','公式依赖根下标从零起；若根从一开始，孩子公式不同。选择实现还要考虑连接大小和操作需求。');
  add('ds-tree-depth-traversals','同一棵树，先读根还是最后读根？','把前、中、后序理解为根相对左右子树的访问时机。',
    '树上 A 是根，左孩子 B，右孩子 C。想把每个字读一次，可以先读 A 再读左右，也可以先读左边 B 再读 A，或者左右都读完才读 A。三种顺序不是树变了，而是对“什么时候正式处理根”作了不同约定。走过节点与输出节点也不总是同一时刻。',
    [['遍历／访问','遍历是按规则处理所有节点；访问指本次正式读取或处理节点的动作。','把字母输出一次。'],['前序','根先于左右子树被访问。','A、B、C。'],['中序／后序','中序为左、根、右；后序为左、右、根。','B、A、C 与 B、C、A。']],
    'compare',[['前序','A、B、C'],['中序','B、A、C'],['后序','B、C、A']],
    [['前序先把当前根处理掉','对 A 先输出 A，再按同样规则遍历左子树 B，最后右子树 C，得到 A、B、C。这里“先”总是针对每一棵子树的根，并非只把整棵树根提前一次就完成。'],['中序把根夹在左右之间','先完成左子树 B，再输出 A，最后完成 C，得到 B、A、C。即使程序已到达 A，也可能先递归去左边，返回时才正式访问 A，不能把“到达”直接当成“输出”。'],['后序等两边完成再处理根','输出顺序为 B、C、A，很适合需要先取得子问题结果再合成根结果的任务。三种算法都应只对真实节点访问，遇到空孩子按规则结束该分支。']],
    '同一二叉树：A 的左孩子 B、右孩子 C，B、C 均无孩子；三块是访问结果对照。','这些是二叉树的左右次序约定；一般树没有天然的“中间那个根”位置，不能无定义套用二叉中序。');
  add('ds-tree-level-order','怎么保证先读完一层，再读下一层？','用队列保存已发现但尚未处理的节点。',
    'A 下接 B、C，B 下接 D，C 下接 E。若希望先读 A，再读 B、C，最后 D、E，就让先排进等候队列的先处理。取出 A 时把它的孩子按左右顺序入队；轮到 B 时再把 D 排到队尾，D 就不会抢在已经等着的 C 前面。',
    [['层序遍历','按离根的层次由近到远处理节点。','A；B、C；D、E。'],['队列','先加入的先取出的等候结构。','先入 B 再入 C，先取 B。'],['发现与处理','发现时安排稍后处理；处理时取出执行本步任务。','D 入队后不立刻越过 C 输出。']],
    'timeline',[['处理 A','队列进入 B、C'],['处理 B','C 等候在前，D 入队尾'],['处理 C','D、E 依次等候下一层']],
    [['根先进入等候区','开始队列只有 A。取出并访问 A，然后把左孩子 B、右孩子 C 依次加入队尾。此时 A 不再等待，队列头为 B，尾为 C。'],['新孩子不能插队到头部','处理 B 后把 D 放在 C 后面，队列成 C、D。若把 D 立即输出或插到队头，就变成先深入一边，失去“先完成同一层”的保证。'],['不断处理直到等候区为空','处理 C 后把 E 加在 D 后面，下一层按 D、E 输出。孩子只有在存在时加入队列；空树则初始不入队。队列峰值与树的宽度有关，不只由高度决定。']],
    '树关系为 A→B、C，B→D，C→E；同一父节点的孩子按左到右入队。','普通树无环，每个节点由唯一父节点发现；若改为一般图，还必须记录已发现状态以避免重复入队。');
  add('ds-tree-reconstruction','只给访问名单，能把树拼回来吗？','用前序找根，再用中序划分左右，并检查标签唯一的前提。',
    '你拿到两张名单：前序是 A、B、C，中序是 B、A、C。前序说第一个 A 是根；中序说 A 左边只有 B、右边只有 C，所以树就能接成 A 的左 B、右 C。关键不是猜形状，而是让两张名单分别提供不同信息：谁是根、谁在左边谁在右边。',
    [['前序首项','当前子树前序中的第一项，是该子树根。','先确认根 A。'],['中序分界','根所在位置把左右子树的节点分开。','B 在 A 左，C 在 A 右。'],['唯一标签','不同节点使用不同标记，才能可靠定位同一根。','两个节点不都叫 A。']],
    'branches',[['前序 A、B、C','首项 A 定根'],['中序 B｜A｜C','左边 B，右边 C'],['拼接子树','A 的左 B、右 C']],
    [['从当前前序取一个根','不是任意找一个字母。当前前序首项 A 必须是这棵子树的根，然后去对应中序范围寻找 A。若找不到，输入就不一致，不能靠猜一个位置继续。'],['用中序数左右各几项','A 左边一项 B，右边一项 C，所以左子树规模一、右子树规模一。这个规模也用来切分剩余前序；不能简单按字符串长度平均分成两半。'],['对子树重复并检查前提','对 B、C 两个单节点子树直接完成。一般情形递归使用同样规则。重复标签会让根定位产生歧义；只有前序与后序而无额外条件，通常也不能唯一确定二叉树。']],
    '前序 A,B,C 与中序 B,A,C 在标签互异时唯一给出本图的二叉树。','唯一重建依赖遍历类型、标签与输入一致性；不要把任意两种遍历都误认为一定能唯一还原。');
  add('ds-threaded-tree','没有孩子的空箭头，能借来指路吗？','区分孩子连接与访问顺序的前驱后继线索。',
    'A 的左孩子 B、右孩子 C，中序读取为 B、A、C。B 没有右孩子，但中序里下一位恰好是 A；可以把原本空着的连接槽借来记录这个后继。这样找下一位时有了路标。不过同一个槽现在可能表示孩子，也可能表示线索，必须另有标记，不然会沿线索当孩子一直绕回。',
    [['中序前驱／后继','在中序访问名单中紧挨着前一位或后一位。','B 的后继是 A。'],['线索','借用空连接记录指定遍历顺序相邻节点。','B 的空右槽指 A。'],['标志位','说明连接当前究竟表示孩子还是线索。','右标志说明“这不是右孩子”。']],
    'compare',[['原树关系','A 左 B、右 C'],['中序名单','B、A、C'],['空槽借路','B 右线索→A；C 左线索→A']],
    [['先有真实树，再定访问次序','原树只有 A 的两条孩子边，中序次序为 B、A、C。前驱后继依赖选定的遍历规则，不等于父节点或某个孩子；换遍历规则，线索对象也可能改变。'],['只借原本允许借用的空槽','B 没有右孩子，可借其空右槽指向中序后继 A；C 没有左孩子，可借空左槽指向前驱 A。真实孩子指针不能被随意覆盖，否则原树结构会丢失。'],['读连接前先检查类型标记','走线索与递归遍历孩子是两种动作。若把 B 到 A 的线索当成右子树继续递归，就可能返回 A 再走 B，形成重复或循环。维护线索时必须同时维护标志约定。']],
    '线索按中序建立；B→A、C→A 是访问路标，不是给原树新增孩子边。','带头节点的线索树还会有边界回接规则，不能用普通空指针叶子判断直接代替所有实现。');
  add('ds-forest-storage-conversion','很多孩子，怎么用“左和右”两条线保存？','理解左孩子指首个孩子、右孩子指下一个兄弟的转换约定。',
    'A 有三个孩子 B、C、D，二叉节点却只有左右两个连接槽。并不是必须丢掉一个孩子；可以让 A 的左线指第一个孩子 B，再让 B 的右线指兄弟 C、C 的右线指兄弟 D。这里的右线换成“下个兄弟”的含义，转换后画成二叉形状，却仍能找回原来的亲子关系。',
    [['一般树／森林','一般树可有多个孩子；森林是一组彼此独立的树。','A 有 B、C、D 三个孩子。'],['孩子兄弟表示','每节点用首孩子和下一兄弟两条连接保存关系。','左指首孩子，右指下一兄弟。'],['兄弟','具有同一个父节点的节点。','B、C、D 都由 A 直接带领。']],
    'branches',[['A 的左连接','指向首孩子 B'],['B 的右连接','指向下一兄弟 C'],['C 的右连接','指向下一兄弟 D']],
    [['先确认原来的亲子关系','A 直接有 B、C、D 三个孩子，三者地位相同，不是 B 的孩子为 C。转换前把这一点写清，避免看到一条向下的图线就误读成原树的父子边。'],['两种连接承担两种语义','A.left 指 B，B.right 指 C，C.right 指 D，分别表示首孩子和下一兄弟。若 B 还有自己的孩子，该孩子由 B.left 引出，不与 B.right 的兄弟链混淆。'],['多棵树也能用兄弟链接起来','森林中各棵树的根可视作同一层的兄弟按约定连接。还原时沿左连接找孩子入口，再沿右连接列出该层兄弟；不是把二叉树每条边都原样当成原树父子边。']],
    '原一般树为 A 的孩子 B、C、D；图中连接按“首孩子／下一兄弟”解释。','表示转换不保证保留二叉图中的层数与原树层数。遍历对应关系需要按新的连接语义重新推导。');
  add('ds-forest-traversal','换成孩子兄弟图后，名单为什么还能对应？','在 A 带 B、C 的小树上核对一般树与二叉表示的访问次序。',
    '原树中 A 带两个孩子 B、C。先根读取就是先 A、再依次 B、C；后根则先处理孩子 B、C，最后才 A。换成孩子兄弟表示后，A 的左连接为 B，B 的右连接为 C。把同一图按二叉前序读，仍是 A、B、C；按二叉中序读，则得到 B、C、A。',
    [['先根／后根','一般树中根在所有子树之前或之后被访问的约定。','先根 A,B,C；后根 B,C,A。'],['孩子兄弟表示','左连接首孩子，右连接下一兄弟。','A.left=B，B.right=C。'],['遍历对应','表示改变后，不同名称的规则可能给出同一名单。','一般树后根对应二叉表示中序。']],
    'compare',[['原树先根','A、B、C'],['二叉表示前序','A、B、C'],['原树后根与中序','都为 B、C、A']],
    [['先直接算原树的两种名单','原树 A 的孩子按 B、C 顺序排列。先根先写 A，再遍历 B 和 C；后根等两个孩子完成后才写 A。先固定孩子次序，才能比较两份结果是否相同。'],['再按新连接真正走一遍','二叉表示中 A 的左子树入口是 B，而 B 的右侧是兄弟 C。前序先 A，随后 B、C，得到 A、B、C；不能把 C 误读成原树 B 的孩子再解释任务关系。'],['用规则验证而不是只背名称','二叉中序先走 A 的左侧，依次处理 B 与它右侧的 C，最后 A，因此为 B、C、A。理解这条路径后，再把一般树后根与二叉中序的对应记住，而不是把后根直接叫二叉后序。']],
    '同一有序一般树 A→B、C 的三份名单；转换采用左孩子右兄弟约定。','森林整体还需按根的兄弟顺序处理；没有指定孩子顺序的无序树，访问名单也没有唯一的左右先后。');
  add('ds-binary-heap','只要随时拿最大值，不必把全部排好','用完全树形与父子大小关系理解最大堆，并追踪新大数上浮。',
    '急诊等候不必把所有人按精确名次排成一条长队，只要每次能快速拿出当前最高优先级。最大堆保证每个父节点不小于孩子，因此根最大；兄弟之间却不要求有序。把新来的 8 放在 7、3、5 后面，再一路与较小的父节点交换，就能恢复这条父子承诺。',
    [['最大堆','形状为完全二叉树且父值不小于各孩子的结构。','根为全堆最大。'],['优先队列','按优先级而非进入时间决定下一项的接口。','每次取最大值。'],['上浮','新元素比父节点更优先时向上交换。','8 从 3 下面升到根。']],
    'timeline',[['原堆','层序数组 7、3、5'],['末尾加入 8','7、3、5、8'],['逐层上浮','8、7、5、3']],
    [['先守形状，再修大小关系','新元素先放完全二叉树的下一个位置，即层序数组末尾。不能为了图好看随便挂在某处，否则下标与父子位置公式可能失效，紧凑形状也不再保证。'],['只沿祖先路径寻找问题','8 的父节点是 3，先交换成 7、8、5、3；再发现 8 大于父 7，再交换成 8、7、5、3。其他分支原本满足父子关系，不需要全部重新排序。'],['只承诺根最优，不承诺全有序','最后 7 和 5 是兄弟，不要求它们在所有表示中形成完整排序。需要有序取出时，要重复移除根并修复堆；把堆数组直接当成从大到小名单会读错。']],
    '图按层序数组展示同一最大堆的插入过程；下标从 0 起。','优先级比较规则须一致。最小堆方向相反；重复值和稳定次序需由接口单独规定，堆本身不自动稳定。');
  add('ds-heapify','一批数建堆，为什么不必一个个从头插？','从最后一个非叶子开始下沉，理解大量底层节点只需少量工作。',
    '已有数组 1、4、3、2，想一次改成最大堆。叶子自己没有孩子，已经满足堆条件；先看较低的父节点，等它的两棵子树都合格，再把它往下调整。这样从底往上建，比想象“每个节点都要走全树高”更省，因为绝大多数节点就在底部附近。',
    [['建堆','把任意合法数组调整为满足堆规则的结构。','1、4、3、2 改为最大堆。'],['下沉','父值太小时与更大的孩子交换，继续向下检查。','1 与 4 交换，再与 2 交换。'],['非叶子节点','至少有一个孩子、可能需要下沉的节点。','四项数组中下标 0、1。']],
    'timeline',[['叶子先合格','3 和 2 无孩子'],['检查父 4','4≥2，不用动'],['根 1 下沉','得到 4、2、3、1']],
    [['跳过不需要调整的叶子','叶子没有孩子，不会违反“父不小于孩子”的规则。零起始数组最后一个非叶子下标为 floor(n/2)−1，本例 n＝4，所以从下标 1 开始，而非从每个元素都走到底。'],['保证较低子树先已成堆','下标 1 的 4 只有孩子 2，无需交换。再处理根时，左右孩子下面的区域已经合格，只需把当前根沿较大孩子方向下沉，便能在局部恢复整棵子树。'],['按各自高度合计工作','本例根 1 先与 4 交换，再与 2 交换，成为 4、2、3、1。一般建堆时很多节点高度为零或一，只有极少数接近树顶；按高度累加后总工作为线性。']],
    '四项数组 1,4,3,2 自底向上建最大堆；floor 表示向下取整。','线性总成本属于这套自底向上算法；逐项插入的一般最坏成本是 n log n，不能把两种方法混为一谈。');
  add('ds-huffman','常见字符用短编码，怎样公平地省总长度？','不断合并最小权重，把出现频率转成根到叶的编码长度。',
    '消息里 A 出现一次，B 两次，C 四次。如果每个字符一律占两位，要用十四位。让最常见 C 用一位，另两个用两位，就只需十位。Huffman 每次合并当前最少的两份权重来建树，最后根到叶上的左右选择形成编码，常见字符就有机会离根更近。',
    [['权重','表示出现频率或需要计入总代价的数量。','A 为 1，B 为 2，C 为 4。'],['前缀编码','没有一个字符编码是另一个字符编码的开头。','0、10、11 可明确分段。'],['带权路径长度','把各权重乘相应根到叶长度，再相加。','4×1＋1×2＋2×2＝10。']],
    'flow',[['合并最小两项','1＋2＝3'],['再合并 3 与 4','形成总权重 7 的根'],['由路径分配编码','C:0，A:10，B:11']],
    [['每次从当前候选里选最小','初始权重 1、2、4，先取 1 与 2 合为新候选 3。原两项成为这个合并节点的两个孩子；下一次比较应使用新候选集合 3、4，不是继续使用原来的 1、2。'],['把合并关系变成二叉树','再合并 3 与 4 得根 7。左右选择可约定为 0 与 1，令 C 位于根的一边，A、B 位于另一边的下一层，于是 C 编码长一位，A、B 长两位。'],['按实际频率计算总费用','一种编码可为 C:0、A:10、B:11，总位数 4×1＋1×2＋2×2＝10。左右对调也可得到另一组同样长度的正确编码，不应把具体 0、1 串当作唯一答案。']],
    '权重为 1、2、4；代码是满足前缀性质的一种选择，重点是长度与合并关系。','Huffman 的最优性针对给定符号权重的二进制前缀编码模型，不代表任意上下文压缩任务都已最优。');
})();
(() => {
  const target=window.PLAIN_BEGINNER;
  function add(id,plainTitle,goal,story,terms,kind,nodes,steps,caption,boundary){target[id]={plainTitle,goal,story,terms:terms.map(([word,meaning,example])=>({word,meaning,example})),diagram:{kind,nodes:nodes.map(([name,detail])=>({name,detail})),caption},steps:steps.map(([title,text])=>({title,text})),boundary};}
  add('ds-stack-core','一摞盘子，为什么最后放的最先拿？','用同一端的加入与取出理解栈，而不是误以为它必须用某种存储。',
    '洗好的盘子从上面放，也从上面拿。先放 A 再放 B，下次自然先拿到 B；想拿下面的 A，得先处理 B。这种限制反而能准确保存“最近没做完的事”。栈规定的就是这套后进先出规则，底层可用数组或链表，盘子的真实摆放并不是定义本身。',
    [['栈','只从指定一端加入和移除、遵守后进先出的结构。','A 后放 B，先取 B。'],['栈顶','允许加入和取出的那一端。','当前最上方的 B。'],['push／pop','push 加入栈顶；pop 取出并移除栈顶。','push(B) 后 pop 得 B。']],
    'timeline',[['放入 A','栈顶为 A'],['再放 B','栈顶为 B'],['取出一次','先得到 B，剩 A']],
    [['先只约定一个出入口','栈不是“所有位置都可以拿”的列表。约定只在栈顶操作后，最近进入且尚未被取出的元素就成为唯一可弹出项，顺序是接口保证而非使用者碰巧遵守。'],['沿顺序记录每次改变','从空栈 push A，再 push B，当前栈底到栈顶为 A、B。记录方向时必须说明哪端是顶，不然同样写 A、B 两个人可能画出相反的取出顺序。'],['取出前也要检查边界','一次 pop 返回 B，并使 B 不再留在栈中。连续再 pop 得 A；第三次面对空栈，需要按接口报错或返回约定结果，不能继续读取不存在的元素。']],
    '图展示三次操作的状态；“上方”是类比，真实实现不要求物理竖着存放。','不同栈接口可能把查看和删除分成 top、pop 两步；使用前先确认具体接口的返回和空栈约定。');
  add('ds-bracket-matching','左右括号一样多，就一定配得上吗？','遇到右括号时匹配最近尚未配对的左括号。',
    '字符串 ([)] 有两个左括号、两个右括号，但仍然不合法：关圆括号时，最近打开的其实是方括号。合法配对像一层层打开盒子，必须先关最里面的那层。因此需要记住“最近还没关闭的左括号”，这正好符合栈最后放入最先取出的规则。',
    [['匹配','括号种类对应且嵌套顺序正确。','( 对应 )，且不能交叉。'],['待配对栈','保存尚未遇到对应右括号的左括号。','读到 ([ 后栈顶为 [。'],['栈顶检查','只查看最近未配对的左括号。','见 ) 时要与栈顶比较。']],
    'timeline',[['读入 ( 与 [','栈底到顶为 (、['],['遇到 )','栈顶是 [，种类不符'],['立即失败','数量相同仍不合法']],
    [['左括号先入栈等候','从左到右读，每遇到左括号就把种类压栈。先读 (，再读 [，表示圆括号外套方括号，最后打开的 [ 应当最先关闭，而非任选一个左括号消去。'],['右括号只和栈顶比较','现在遇到 )，若栈为空就是没有对应左括号；本例不空，但顶端为 [，种类不同，因此判错。不能跳过顶端往更底下找 (，那样会允许交叉嵌套。'],['扫描完还需检查栈是否空','合法闭合时，右括号让对应栈顶弹出。即使一路没有种类冲突，读完整串后若栈还非空，也说明有左括号没被关闭；所以中途检查和结尾检查缺一不可。']],
    '图专门追踪反例 ([)] 的首次冲突；不是说所有等数量的输入都失败。','此算法假设已经识别出要检查的括号；真实程序语言中的字符串、注释等内容可能需要先按语法分辨。');
  add('ds-expression-stack','为什么 2＋3×4 不能从左往右一律相加？','先按优先级安排操作，再用栈执行后缀表达式。',
    '算 2＋3×4 时，必须先做乘法，再把结果加 2。平常的写法让运算符夹在数字中间，需要认识优先级和括号；后缀写法把运算放在它的两个输入之后，例如 2 3 4 × ＋。这样读到一个运算符时，最近准备好的两个值正好在栈顶。',
    [['中缀表达式','运算符放在输入之间的常见写法。','2＋3×4。'],['后缀表达式','先列输入，再写作用于它们的运算。','2 3 4 × ＋。'],['优先级','没有括号另行指定时，决定谁先结合的规则。','乘法先于加法。'],['操作数','参与一次运算的输入值。','3×4 的输入是 3 和 4。']],
    'timeline',[['读 2、3、4','三个值依次入栈'],['读 ×','弹 4、3，压入 12'],['读 ＋','弹 12、2，压入 14']],
    [['先把结合顺序表达清楚','2＋3×4 的乘法要先做，因此对应后缀为 2 3 4 × ＋，不是 2 3 ＋ 4 ×。中缀转后缀时，用运算符栈和优先级安排这个输出次序，括号也要参与控制。'],['读到数字时先存起来','求值栈依次收到 2、3、4。见 × 时，先弹出右输入 4，再弹出左输入 3，算出 12 压回。相加相乘看不出左右差异，遇到减法除法就不能交换顺序。'],['每个运算把输入合成结果','再见 ＋，取出 12 与 2，计算 2＋12 得 14。有效二元后缀表达式不应中途缺两个输入，结束时也应只剩一个结果；多余值或缺值都值得检查。']],
    '图展示后缀求值，而非中缀转写算法本身；栈中数值从底到顶按读入顺序增加。','这里只含二元运算。负号、一元运算、函数和不同结合性的符号，需要在词法和优先级规则里单独规定。');
  add('ds-circular-queue','排队的人从一端进，另一端出','用循环下标复用空格，并说清怎样区分队空和队满。',
    '窗口排队通常先来先服务：新人站到队尾，窗口从队头叫人。若用一排数组模拟，前面的人离开后，空位不该永远浪费。循环队列让下标走到数组末端后回到开头，但这只是存放位置绕圈，服务顺序仍然保持先入先出。',
    [['队列','从队尾加入、从队头移除，先入先出的结构。','先到 A，后到 B，先取 A。'],['front／rear','这里分别记下一个出队位置和下一个入队位置。','rear 指下一格可写处。'],['取模 %','取除法余数，用来让下标绕回范围内。','(3＋1)%4＝0。']],
    'cycle',[['队尾加入','写 rear 指向的位置'],['下标绕回','新 rear＝(rear＋1)%4'],['队头离开','front 按同样规则前进']],
    [['先约定两个指针各指什么','本图用 front 指下个要取的位置，rear 指下个要放的位置。不同教材也会让 rear 指最后一个已有元素，公式因此不同；先确定约定，再判断入队要先写还是先移动。'],['跨末端只改下标，不改队列次序','数组容量四，rear 在 3 写完后变成 0，继续利用前方已释放的位置。先入的元素仍从 front 依次取出；“循环”说的是存储复用，不是把人随机插进队伍。'],['单独保留队满队空信息','front 与 rear 相等可能来自空，也可能绕一整圈后满。可以另记元素个数，或约定留一格不用；采用后一种时，满条件是下一 rear 将碰到 front，而实际可装容量减一。']],
    '图假设数组大小四，采用“rear 指下个写入位置”的约定；空满策略需另行选定。','取模公式只负责绕回，不能替代满队列检查。不要混用“留空一格”和“计数器判满”两套容量结论。');
  add('ds-deque-window','窗口往右走，怎样少看一些不可能赢的数？','用下标维护窗口最大值候选，区分过期淘汰和被更大值淘汰。',
    '一排数 2、1、3、0，每次只看相邻三项，想快速得到窗口最大值。3 到来时，前面的 1 和 2 不仅更小，还更早离开窗口，往后都不可能比 3 更值得保留。用能从两端操作的队列保存候选下标，就可把这种“再也不会赢”的候选及时删掉。',
    [['双端队列','两端都能加入或移除的队列结构。','队头查最大，队尾删弱候选。'],['滑动窗口','按固定规则向前移动的一段输入范围。','长度三的连续区间。'],['单调队列','让候选值按指定顺序排列的双端队列用法。','最大值候选从头到尾不增。']],
    'timeline',[['窗口先收 2、1','候选下标为 0、1'],['3 到来','从尾删去 1 与 2'],['队头给答案','首窗口最大值为 3']],
    [['候选要保存位置而非只存值','用下标才能判断某个元素是否已离开窗口。先看到 2 和 1，候选按值从大到小排列，2 在头、1 在尾；它们都是目前仍有机会成为某次最大值的元素。'],['新来的更大且活得更久','下标 2 的 3 到来时，从尾依次淘汰较小的 1、2。它们值不如 3，位置又更早过期，因此未来只要它们还在窗口，3 也在且更大，保留它们没有必要。'],['先去过期项，再读队头','窗口形成后，移除队头所有下标已小于当前窗口左界的候选，再看队头即最大值。每个下标至多入队和出队一次，因此全过程可线性处理，而非每窗重新扫描。']],
    '追踪长度三窗口 [2,1,3]；随后窗口 [1,3,0] 最大值仍为 3。','相等值可选保留或淘汰其中一个，但比较符号与过期规则必须一致；本法依赖窗口沿输入单向前进。');
  add('ds-recursion-stack','把问题交给更小的自己，何时才能停？','认出终止条件、缩小方式和等待返回的记录。',
    '求 1 到 3 的和，你可以说“先求 1 到 2 的和，再加 3”；求到 1 时直接回答 1。这不是把任务凭空甩掉，而是给规模更小的同一种问题一个清晰请求。每层还得记住回来后加哪个数，因此递归既要会停，也要管理尚未完成的等待。',
    [['递归','函数通过调用自身等方式解决更小的同类问题。','sum(3) 先求 sum(2)。'],['基例','不再递归、可以直接回答的边界情况。','sum(1)＝1。'],['调用栈','保留尚未结束调用所需状态的机制。','记住回到上层还要加 3。']],
    'layers',[['sum(3) 等待','先请求 sum(2)，回来加 3'],['sum(2) 等待','先请求 sum(1)，回来加 2'],['sum(1) 直接答','1 返回，逐层得 3、6']],
    [['每次调用先检查能否直接回答','本例规定 n 为正整数，n＝1 时返回 1。必须在继续调用之前检查基例，否则规模不断下降也可能越过该停的位置，最后陷入无效调用而不能正常完成。'],['说明为什么真的变小','sum(n) 请求 sum(n−1)，离基例更近；上层暂存“收到结果后再加 n”。只有相信一个定义良好的更小问题，才能把大问题分解，不能用原规模直接再次请求自己。'],['把返回过程也走一遍','sum(1) 给出 1，sum(2) 算 1＋2＝3，再让 sum(3) 算 3＋3＝6。最大同时等待层数与 n 相关，需要栈空间，写法简短并不代表额外空间为零。']],
    '图自外层到内层展开请求，实际结果按相反方向返回。','这里 n≥1；若允许 n＝0 或负数要另定契约。不要在未经验证时假设编译器会自动消除全部递归栈开销。');
  add('ds-backtracking','走错一条岔路，怎样退回来重选？','把每个选择、尝试和撤销对应起来，避免分支相互污染。',
    '要用 A、B 排出所有顺序，先试第一个位置放 A，再放 B，得到 AB；然后必须把刚放的选择撤销，回到空位继续试 B、A，得到 BA。回溯像在岔路留脚印：沿一个选择深入，把这条分支探索完，再恢复到岔路时的状态。',
    [['搜索树','把各阶段选择画成根到分支的所有可能。','第一位可选 A 或 B。'],['回溯','试完一个分支后撤销选择，回到之前状态继续尝试。','AB 完成后移走 B 再移走 A。'],['剪枝','根据可靠条件，提前停止不可能产生合法答案的分支。','已用 A，就不再选 A。']],
    'branches',[['第一位 A','继续选未用的 B'],['记录 AB','得到一个完整排列'],['撤销再选 B','再选 A，记录 BA']],
    [['先保存可检查的当前状态','当前排列为空，A、B 都未使用。选择 A 时，要同时把 A 放进路径并标成已用，后续才能知道哪些选择还合法；路径与使用标记必须表达同一个事实。'],['沿一个分支走到完成','剩下 B 可选，得到 AB，记录答案。若答案存放的是可变路径的引用，之后撤销可能连答案也改掉，应按语言和结构保存独立结果，而不是只存同一个工作对象。'],['回到分岔处必须恢复现场','撤销 B 与 A，并恢复它们的未用标记，才可从空路径尝试 B。少撤一个标记，会让别的分支误以为 A 还占用；回溯正确性依赖选择与撤销严格配对。']],
    '这是两元素排列的部分搜索树；箭头表示选择依赖，不是最终答案的字典顺序保证。','剪枝必须证明不会删去合法答案。回溯可能仍需指数或阶乘级工作，不能因为有剪枝就默认高效。');
  add('ds-naive-string-search','对不上一个字，下一次从哪里重新试？','用文本 abac 与模式 ac 追踪朴素匹配的起点。',
    '在一句长文本里找短词，就像拿一条写着 ac 的透明纸，先对齐长条 abac 的开头，逐字比较。某处不符，就把透明纸整体右移一格，从模式第一个字重试。朴素匹配的“朴素”指这种直接办法，不是随意跳过字符；文本起点和模式内部位置要分别记。',
    [['文本','被搜索的完整字符序列。','abac。'],['模式','想在文本中找的短序列。','ac。'],['匹配起点','这次让模式开头对齐文本的哪个下标。','先试 0，再试 1、2。']],
    'timeline',[['起点 0','a 相同，b 与 c 不同'],['起点 1','b 与 a 不同'],['起点 2','a、c 全相同，找到']],
    [['固定起点后逐字比较','起点 0 时，模式 a 对文本 a，相同；下一对是模式 c 对文本 b，不同，因此这次起点失败。不是文本里出现过一个 a 就等于整个模式已经出现。'],['失败后整体移动一格','起点变成 1，模式位置重新从 0 开始，b 与 a 当场不同。文本候选起点和本轮模式进度是两个变量，若混在一起更新，容易漏试或重复试同一个位置。'],['整段相等才记录成功','起点 2 时依次比较 a 对 a、c 对 c，都成功，返回下标 2。只需尝试到剩余文本长度仍容纳整个模式的位置；空模式怎样返回应由接口另外约定。']],
    '三个状态对应同一文本 abac、同一模式 ac；下标从 0 起。','最坏时许多起点会重复比较长前缀，成本可能接近文本长乘模式长；本例短小不代表总是线性。');
  add('ds-prefix-function','失败以前已经相同的部分，能留下多少？','用 ababa 的首尾共同部分理解前缀函数，而非先背公式。',
    '模式 ababa 的开头三字是 aba，结尾三字也恰好是 aba。若正在匹配的一长段随后失败，这个重复结构告诉我们：不是所有已经比较过的信息都要丢掉，可以把末尾的 aba 当作新一轮开头。这种“最长、但不能是整串自己的共同首尾长度”，就是前缀函数要记录的核心。',
    [['前缀／后缀','分别从开头截取、从结尾截取的连续一段。','ababa 的前三字与后三字都是 aba。'],['真前缀','长度严格小于整串的前缀。','ababa 自己不能算真前缀。'],['π／前缀函数','π[i] 记录模式从 0 到 i 的前段，最长相等真前后缀的长度。','ababa 的 π[4]＝3。']],
    'compare',[['前段 ababa','不允许取整个自己'],['开头与末尾','aba 与 aba 相同'],['最长长度','π[4]＝3']],
    [['先明确在研究哪一段','π[4] 研究的是下标 0 到 4，共五个字符 ababa。这里的函数输入不是文本位置，也不是下一次从文本哪一格开始，而是描述模式自身每一段的重复结构。'],['列出不同长度的首尾','长度一的首尾都是 a；长度二为 ab 与 ba，不相等；长度三都是 aba，相等；长度四为 abab 与 baba，不相等。因此最长合格长度是三。'],['最长值不把整串算进去','整串当然总等于自己，但保留整串会使失败回退没有进展，所以必须要求真前后缀。计算 π 数组时可以复用前面的短边界；先能人工列出此例，再读 j 回退公式会更有依据。']],
    '图并列比较同一段 ababa 的前后缀，未表示三个字符在内存中额外复制。','不同教材的 next、nextval 与 π 定义可能采用不同下标和含义；不能只看数组名字就直接代入同一个公式。');
  add('ds-kmp-search','为什么文本不回头，也不会漏掉短词？','用已匹配前段的首尾重合移动模式，不盲目重新扫描文本。',
    '在 ababac 中找 abac，开头先配上 aba，却在第四字遇到 b 与 c 不同。已经配上的 aba 末尾还有一个 a，正好能接模式开头，所以可以保留这一字，再用当前 b 比模式的第二字 b。KMP 利用的就是模式自身重复信息：文本指针不必倒退，也没有把必要候选随意略掉。',
    [['KMP','利用模式的前后缀信息避免重复回退文本的匹配算法。','匹配失败时调整模式已配长度。'],['已配长度 j','当前已连续匹配模式开头多少字。','aba 配上后 j＝3。'],['失败回退','按已配前段的最长真前后缀缩短 j。','aba 保留后缀 a，j 退到 1。']],
    'timeline',[['先配上 aba','第四字 b 对 c 失败'],['保留末尾 a','已配长度从 3 退到 1'],['当前 b 继续比','随后配出起点 2 的 abac']],
    [['失配发生时先停住文本位置','文本前三字 aba 与模式前三字相同。现在当前文本字是下标 3 的 b，而模式期待 c。先别把文本移走，更别盲目回到开头；已匹配前段里还有可复用信息。'],['通过模式自身结构保留尾部','aba 的最长相等真前后缀是 a，长度一，因此把已配长度退为 1。意思是已经见到的最后那个 a，可以充当新一轮模式的开头；无需再拿文本去重新证明它。'],['再比较当前尚未消耗的字','当前文本 b 与模式下标 1 的 b 相同，继续后面的 a、c，最终在文本下标 2 起匹配成功。若回退后仍不等，要继续按失败信息退，而不是只允许回退一次。']],
    '文本 ababac、模式 abac；先失败的位置为文本下标 3，成功起点为 2。','线性结论要求失败回退规则正确、字符比较成本受控；π 与其他 next 约定不能混用。');
  add('ds-multidimensional-array','二维表先铺平，再找目标位置','数清前面整行与本行元素，再换成字节距离。',
    '一张两行三列的表，纸上是长方形，内存里可以按行铺成一条带：第一行三个元素放完，再放第二行三个。要找第二行第三项，先越过第一行三项，再越过本行前两项，共五项。知道每项大小后，就能把五项换成具体地址距离。',
    [['行优先','先按顺序存完整行，再接下一行的布局。','两行各三项。'],['下标','指定第几个位置的编号，本课从 0 开始。','a[1][2] 为第二行第三项。'],['字节偏移','目标起点离整个数组起点多少字节。','五个四字节元素为 20 字节。']],
    'memory',[['前一整行','先跳 3 项'],['本行前两项','再跳 2 项，共 5 项'],['目标起点','1000＋5×4＝1020']],
    [['先确认一行到底有几项','本例每行三项，行下标 1 意味前面只有一整行，先跨 1×3＝3 项。行数和列数不能互换，否则会把每行跨度算错，得到另一块位置。'],['加上目标行里已跨的列','列下标 2 表示该行前面还有两项，所以总共跳过 3＋2＝5 项。先数元素再乘类型大小，比一开始混合行列、字节和地址更容易检查单位。'],['最后换单位并加起点','假设每项四字节，五项是二十字节；首地址 1000 加二十得 1020。直接 C 二维数组是连续行数组，不等于一组指向分散行的二级指针。']],
    '真正连续的 C 二维数组教学例；地址与 int 四字节都是本题假设。','其他语言和库可能采用列优先或带步长视图，访问前先确认布局，不能把同一公式当成所有二维对象的规定。');
  add('ds-symmetric-triangular','半张表就能表达整张对称表吗？','用下三角按行压缩，先数前面有多少项再推下标。',
    '三乘三表若关于主对角线对称，上方的值能从下方对应位置找到，就不必存两份。按行只留对角线及下方：第一行一项，第二行两项，第三行三项。找某一格时，先数前面行各存多少，再数本行走几格；公式来自这个计数，而不是凭空出现。',
    [['主对角线','行列编号相同的一组格子。','位置 (0,0)、(1,1)、(2,2)。'],['对称矩阵','交换行列后对应元素相等的矩阵。','A[0][2]＝A[2][0]。'],['压缩下标','目标在只保存有效格的一维数组里的位置。','下三角第 i 行前有 i(i＋1)/2 项。']],
    'layers',[['第 0 行','存 1 项'],['第 1 行','存 2 项，前面 1 项'],['第 2 行','存 3 项，前面 3 项']],
    [['先明确保留哪一半','本例保留包含对角线的下三角，行列从零编号。若目标在上半部分，先交换行列来到对称的下半位置；这一转换依赖对称性，不适用于任意普通矩阵。'],['数目标之前完整行的项数','第 i 行之前共有 1＋2＋…＋i 项，也就是 i(i＋1)÷2。第 2 行之前是一项加两项，共三项，因此该行开头在压缩数组下标 3。'],['再加本行的列偏移','下三角目标 (2,1) 从该行开头再走一格，得到下标 3＋1＝4。公式 k＝i(i＋1)/2＋j 只在这套保留方式、零起始下标且 i≥j 时使用。']],
    '图展示三阶对称矩阵保留下三角的行长度，不是三行实际数值。','若教材只存严格三角、把对角线单独保存或采用一开始编号，公式会改变，必须先确定布局约定。');
  add('ds-sparse-matrix','大表几乎全是零，能只记有用格吗？','用行、列、值记录非零项，转置时交换坐标并整理顺序。',
    '一百乘一百的表只有两格不是零，若还为每个零留位置就很浪费。可以只记“第几行、第几列、值是多少”，像标地图上的两个地点。这就是三元组保存稀疏矩阵的想法。把表转置时，行与列交换；但若要求记录仍按行排列，还得重新组织次序。',
    [['稀疏矩阵','非零项相对总格子很少的矩阵。','大部分格子都是零。'],['三元组','记录行号、列号和数值的一条记录。','(0,2,5)。'],['转置','把原来的行列角色互换。','(0,2,5) 变 (2,0,5)。'],['行指针','记录各行有效项从存储序列哪里开始的索引信息。','可快速定位某行。']],
    'flow',[['原非零项','(0,2,5)、(2,0,7)'],['交换行列','(2,0,5)、(0,2,7)'],['按新行整理','(0,2,7)、(2,0,5)']],
    [['先记尺寸，再省略默认零','只记录非零三元组还不够表达完整尺寸，另须记矩阵有几行几列。未列出的格子按零理解；若输入允许同一坐标重复出现，还要规定合并方式。'],['交换每条记录的两个坐标','原 (0,2,5) 表示第零行第二列为五，转置后变第二行第零列，值仍为五。数值不交换、不取负，改变的是坐标角色。'],['根据访问要求整理位置','交换后记录不一定按新行有序。快速转置可先计原各列项数，确定新各行起点，再把元素放进正确区域；不能只说“改两个数字”就完成所有存储契约。']],
    '以三乘三矩阵的两个非零项为例；图中坐标从 0 起。','稀疏表示也有坐标开销；非零项很多时未必节省空间。零值阈值、重复坐标和排序要求由数据接口明确。');
  add('ds-generalized-list','一个表里再装一个表，长度怎么算？','区分顶层元素数、表头表尾和最深嵌套层数。',
    '盒子里放一颗珠子 a、一个装着 b 和 c 的小盒子，以及一个空小盒子。站在最外层看，一共是三个东西，而不是把里面的珠子全数一遍。广义表允许元素本身仍是表，所以长度看顶层有几项，深度则看最深套了几层；“后面剩的表”和“最后一个元素”也不同。',
    [['原子','这里指不再作为表拆分的基本元素。','a、b、c。'],['表头／表尾','表头是第一个元素；表尾是删去首元素后剩下的表。','(a,b) 的尾是 (b)。'],['长度／深度','长度数顶层项数；深度按本课约定数最深表层数。','(a,(b,c),()) 长 3、深 2。']],
    'layers',[['外层表','a、(b,c)、() 共三项'],['表头与表尾','头 a；尾 ((b,c),())'],['最深表层','内表再套一层，深度 2']],
    [['先按括号找顶层分隔','写作 (a,(b,c),()) 时，顶层有 a、(b,c)、() 三个元素。内表中的逗号不再增加外层长度，空表也可以作为一个顶层元素出现，不能把它自动删掉。'],['把尾看成仍然包着括号的表','表头为原子 a，表尾是由后面两项组成的 ((b,c),())，它的长度为二。表尾不是最后一个元素，也不是把后面内容去掉所有括号。'],['单独计算嵌套深度','采用原子深度零、空表深度一的约定，外层再包含一层内表，所以最深为二。长度与深度回答不同问题；只有一个元素的表也可能套很多层。']],
    '括号表示包含关系，不是链表箭头；深度采用原子 0、空表 1 的约定。','广义表可能有共享或递归结构，简单嵌套图没有覆盖所有实现；题目给出不同深度约定时要据此调整。');
})();
